/* ═══ dr-atelier.js — L'ATELIER (E1) : les gestes sur la trame, la répétition, les schémas dans l'atelier, écrire dans la diapo, les notes, la mise en forme (maquette p8-5g l. 973-1251) ═══ */

/* ── (p3) l'atelier : les gestes sur la trame, tous par identité ── */
function toast(msg){ let t = $('at-toast'); if (!t) { t = document.createElement('div'); t.id = 'at-toast'; t.style.cssText = 'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:#1c1712;color:#e8dcc4;border:1px solid var(--or);border-radius:10px;padding:8px 14px;font-size:.9rem;z-index:90;max-width:70vw'; dr_zone()/* E1 : lisait document.body */.appendChild(t); } t.textContent = msg; t.style.display = 'block'; clearTimeout(t._t); t._t = setTimeout(() => { t.style.display = 'none'; }, 4000); }

const nouvelEid = () => 'e' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
 const nouveauBid = () => 'b' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);

const roleFixe = e => e.role === 'fin' ? 'la diapo de fin d\'heure' : e.role === 'bilan' ? 'le bilan de la séance' : e.role === 'reactivation' ? 'la réactivation' : null;

function apresTrame(quoi){ reindexer(); if (S.ordres) { Object.keys(S.ordres).forEach(h => { if (!(S.closes && S.closes[h]) && !(S.lancee && +h === S.heure)) delete S.ordres[h]; }); } marquerModif(quoi); dr_tout(); }

function cloneBloc(b){ const c = JSON.parse(JSON.stringify(b)); c.bid = nouveauBid(); return c; }

function dupliquerDiapo(i){ const E = seance().ecrans; const e = E[i]; const rf = roleFixe(e); if (rf) return alert(rf + ' ne se duplique pas.'); const c = JSON.parse(JSON.stringify(e)); c.eid = nouvelEid(); c.act = e.act + ' (copie)'; c.blocs = (c.blocs || []).map(cloneBloc); delete c.ajouteeALImport; E.splice(i + 1, 0, c); apresTrame({ di: i, duplique: c.eid }); S.di = i + 1; dr_tout(); }

function insererDiapoApres(i){ const E = seance().ecrans; const e = E[i]; if (e.role === 'bilan') return alert('Rien ne s\'insère après le bilan : il reste le dernier de la séance.'); if (e.role === 'fin') return alert('Rien ne s\'insère après la fin d\'heure : insère avant elle.'); const c = { eid: nouvelEid(), act: 'Nouvelle diapo', heure: e.heure, dur: 5, role: null, comp: [], blocs: [{ t: 'consigne', bid: nouveauBid(), txt: 'Nouvelle diapo', el: [''] }], actId: e.actId }; E.splice(i + 1, 0, c); apresTrame({ di: i, insere: c.eid }); S.di = i + 1; dr_tout(); }

function deplacerDiapo(i, sens){ const E = seance().ecrans; const e = E[i]; const rf = roleFixe(e); if (rf) return alert(rf + ' ne se déplace pas : elle reste à sa place dans son heure.'); const j = i + sens; if (j < 0 || j >= E.length) return; const v = E[j]; if (v.role === 'bilan' && sens > 0) return alert('Rien ne passe après le bilan.'); if (v.role === 'reactivation' && sens < 0) return alert('Rien ne passe avant la réactivation.'); let dit = ''; if (v.role === 'fin' && sens > 0) { /* on franchit la frontière d'heure : la diapo change d'heure prévue, la fin d'heure reste la dernière de la sienne */ const hSuiv = E.slice(j + 1).find(z => z.heure !== e.heure); if (!hSuiv) return alert('Il n\'y a pas d\'heure après : la fin d\'heure reste la dernière.'); E.splice(i, 1); E.splice(j, 0, e); e.heure = hSuiv.heure; dit = `elle passe en H${e.heure}`; } else if (v.heure !== e.heure) { E.splice(i, 1); E.splice(j, 0, e); const anc = e.heure; e.heure = v.heure; dit = `elle passe en H${e.heure} (elle était en H${anc})`; } else { E[i] = v; E[j] = e; } apresTrame({ di: i, deplace: e.eid, vers: j, heure: e.heure }); S.di = indexDe(e.eid); if (dit) toast('Diapo déplacée : ' + dit + ' — le compte des heures est recalculé.'); dr_tout(); }

function supprimerDiapo(i){ const E = seance().ecrans; const e = E[i]; const rf = roleFixe(e); if (rf) return alert(rf + ' ne se supprime pas.'); const vue = !!vuMax[K(i)] || J.some(x => x.type === 'diapo' && x.eid === e.eid); if (!confirm('Supprimer « ' + e.act + ' » de la trame ?' + (vue ? ' Une classe l\'a déjà vue : elle la garde dans sa copie, seule la trame change.' : ''))) return; E.splice(i, 1); apresTrame({ supprime: e.eid, vue }); S.di = Math.min(i, E.length - 1); dr_tout(); }

function couperDiapoIci(i, bi){ const E = seance().ecrans; const e = E[i]; if (!bi || bi >= (e.blocs || []).length) return alert('Choisis un bloc qui n\'est pas le premier : la diapo se coupe avant lui.'); const suite = JSON.parse(JSON.stringify(e)); suite.eid = nouvelEid(); suite.act = e.act + ' (suite)'; suite.blocs = e.blocs.slice(bi); e.blocs = e.blocs.slice(0, bi); suite.dur = Math.round((e.dur || 0) / 2); e.dur = (e.dur || 0) - suite.dur; E.splice(i + 1, 0, suite); p8NotesCouper(i, bi, suite.eid); /* (p8-5c) chaque paragraphe suit son élément */ apresTrame({ di: i, coupe: bi, suite: suite.eid }); toast('Diapo coupée : « ' + suite.act + ' », même heure, mêmes notions.'); dr_tout(); }

function envoyerVersSeance(i){ const E = seance().ecrans; const e = E[i]; if (dr_seances()/* E1 : lisait DATA.seances */.length < 2) return alert('Une seule séance dans le chapitre : rien où envoyer.'); fermerChoix(); const z = document.createElement('div'); z.className = 'choix-obj'; const dur = e.dur || 0; const compte = (sc, h) => sc.ecrans.filter(x => x.heure === h && x.role !== 'fin').reduce((t, x) => t + (x.dur || 0), 0); const oH = ordreHeure(e.heure); const resteIci = oH.filter(q => q !== i && E[q].role !== 'fin').reduce((t, q) => t + (E[q].dur || 0), 0); z.innerHTML = `<h4><span>ENVOYER « ${dr_esc(e.act)} » VERS UNE AUTRE SÉANCE — identité inchangée, heure recalculée à l'arrivée</span><span class="x">✕</span></h4><div class="form">${dr_seances()/* E1 : lisait DATA.seances */.map((sc, k) => { if (k === S.si) return ''; const heures = [...new Set(sc.ecrans.map(x => x.heure))].sort((a, b) => a - b); return `<div class="fe"><b>Séance ${k + 1} — ${dr_esc(sc.titre || '')}</b> · ${heures.length} heure${heures.length > 1 ? 's' : ''}<br>${heures.map(h => { const c = compte(sc, h) + dur + 5; return `<span class="fi" data-si="${k}" data-h="${h}" style="${c <= 50 ? 'background:#fff7e0' : ''}" title="La diapo arrive avant la fin d'heure de H${h} ; ses notions et ses réponses d'élèves la suivent">à la fin de H${h} · ${compte(sc, h)} + ${dur} + 5 = ${c} min${c > 50 ? ' +' + (c - 50) : ' ✔'}</span>`; }).join('')}</div>`; }).join('')}<div class="dr-err" style="color:#6a5a48">Ici, elle sort du compte : l'heure ${e.heure} revient à ${resteIci} + 5 = ${resteIci + 5} min${resteIci + 5 > 50 ? ' +' + (resteIci + 5 - 50) : ' ✔'}.</div></div>`; document.querySelector('.scene').appendChild(z); z.querySelector('.x').onclick = fermerChoix; z.querySelectorAll('[data-si]').forEach(b => b.onclick = () => { const k = +b.dataset.si, h = +b.dataset.h; const cible = dr_seances()/* E1 : lisait DATA.seances */[k]; E.splice(i, 1); const anc = e.heure; e.heure = h; delete e.actId; let pos = cible.ecrans.length; for (let q = cible.ecrans.length - 1; q >= 0; q--) { if (cible.ecrans[q].heure === h && cible.ecrans[q].role !== 'fin' && cible.ecrans[q].role !== 'bilan') { pos = q + 1; break; } if (cible.ecrans[q].heure === h && cible.ecrans[q].role === 'fin') pos = q; } cible.ecrans.splice(pos, 0, e); fermerChoix(); apresTrame({ envoye: e.eid, vers: k, heure: h, de: anc }); S.di = Math.min(i, E.length - 1); toast('Diapo envoyée vers la séance ' + (k + 1) + ', à la fin de H' + h + ' — identité inchangée.'); dr_tout(); }); }

function menuAtelierDiapo(i, x, y){ const E = seance().ecrans; const e = E[i]; const a = actDe(e); const rf = roleFixe(e); const h = e.heure; const o = ordreHeure(h); const enTete = `${e.role === 'fin' ? 'Cahier de textes (fin d\'heure)' : e.act}${a ? ' · A' + a.num : ''} · H${h}`;
  let noteDesc = ''; const j = i + 1; if (!rf && E[j] && E[j].role === 'fin') { const hS = E.slice(j + 1).find(z => z.heure !== h); if (hS) { const p1 = o.filter(k => E[k].role !== 'fin' && k !== i).reduce((t, k) => t + (E[k].dur || 0), 0); const p2 = ordreHeure(hS.heure).filter(k => E[k].role !== 'fin').reduce((t, k) => t + (E[k].dur || 0), 0) + (e.dur || 0); noteDesc = `↓ en descendant, elle passe en H${hS.heure} : l'heure ${h} revient à ${p1} + 5 = ${p1 + 5} min${p1 + 5 - 50 > 0 ? ' +' + (p1 + 5 - 50) : ' ✔'}, l'heure ${hS.heure} monte à ${p2 + 5} min${p2 + 5 - 50 > 0 ? ' +' + (p2 + 5 - 50) : ' ✔'}`; } }
  const items = [{ a: 'titre', l: enTete, off: true }, '-', { a: 'ouvrir', l: 'Ouvrir', t: 'Entrée — la diapo dans l\'atelier', off: i === S.di }, { a: 'dupliquer', l: 'Dupliquer', off: !!rf, t: rf ? rf + ' ne se duplique pas (2.6)' : 'Ctrl + D — une nouvelle diapo juste après, mêmes blocs, nouvelle identité (les réponses d\'élèves n\'y sont pas), notions copiées, heure héritée' }, { a: 'inserer', l: 'Insérer une diapo après', off: e.role === 'bilan' || e.role === 'fin', t: e.role === 'bilan' ? 'rien après le bilan' : e.role === 'fin' ? 'rien après la fin d\'heure : insère avant elle' : 'Ctrl + Entrée — une diapo vide juste après, dans la même heure, sans rôle' }, '-', { a: 'monter', l: 'Monter', off: !!rf || i === 0, t: rf ? rf + ' reste à sa place' : 'Alt + ↑ — l\'ordre change, pas l\'identité : ce que la classe a fait sur cette diapo la suit' }, { a: 'descendre', l: 'Descendre', off: !!rf || i >= E.length - 1, t: rf ? rf + ' reste la dernière de son heure' : 'Alt + ↓ — si elle franchit la frontière d\'heure, elle change d\'heure prévue et le site le dit' }, ...(noteDesc ? [{ a: 'note', l: noteDesc, off: true, ss: true }] : []), { a: 'envoyer', l: 'Envoyer vers une autre séance…', off: !!rf || dr_seances()/* E1 : lisait DATA.seances */.length < 2, t: dr_seances()/* E1 : lisait DATA.seances */.length < 2 ? 'une seule séance dans la maquette' : 'identité inchangée, heure recalculée à l\'arrivée' }, '-', { a: 'couper', l: 'Couper la diapo ici…', off: !!rf || (e.blocs || []).length < 2, t: (e.blocs || []).length < 2 ? 'un seul bloc : rien à couper' : 'ouvre la diapo : clic droit sur le bloc où couper (0.4)' }, { a: 'supprimer', l: 'Supprimer', off: !!rf, t: rf ? 'chaque heure garde ' + rf + ' (1.4)' : 'Suppr — une classe qui l\'a déjà vue la garde dans sa copie ; les notions du chapitre se recalculent' }];
  menuA($('menu'), x, y, items); $('menu').onclick = ev => { const b = ev.target.closest('[data-a]'); if (!b || b.disabled) return; $('menu').classList.remove('on'); const act = b.dataset.a; journal('atelier-menu', { di: i, action: act }); if (act === 'ouvrir') { S.di = i; S.page = null; dr_tout(); } if (act === 'dupliquer') dupliquerDiapo(i); if (act === 'inserer') insererDiapoApres(i); if (act === 'monter') deplacerDiapo(i, -1); if (act === 'descendre') deplacerDiapo(i, 1); if (act === 'envoyer') envoyerVersSeance(i); if (act === 'couper') { S.di = i; S.page = null; dr_tout(); toast('Clic droit sur le bloc où couper, puis « Couper la diapo ici ».'); } if (act === 'supprimer') supprimerDiapo(i); }; }

function menuAtelierMur(ev){ const g8 = ev.target.closest && ev.target.closest('#mur .p8-dessin g.p8-n, #mur .p8-dessin .p8-grille tr'); if (g8) { p8MenuBulle(g8, ev); return; } /* (p8-3) décision 5 */ const li = ev.target.closest('li[data-p]'); const blocEl = ev.target.closest('[data-bi]') || ev.target.closest('[data-bloc]'); const e = ecran(); if (!e || e.role === 'fin') return; const bi = blocEl ? +(blocEl.dataset.bi != null ? blocEl.dataset.bi : blocEl.dataset.bloc) : (li ? +li.dataset.p.split('.')[0] : null); if (bi == null || !e.blocs[bi]) return; const b = e.blocs[bi]; const n = (b.el || []).length; const ei = li && li.dataset.p.split('.')[1] !== 't' ? +li.dataset.p.split('.')[1] : null;
  if (ei != null) { const items = [{ a: 'titre', l: `Élément ${ei + 1} sur ${n} · bloc ${bi + 1}`, off: true }, '-', { a: 'e-dupliquer', l: 'Dupliquer l\'élément' }, { a: 'e-monter', l: 'Monter', off: ei === 0 }, { a: 'e-descendre', l: 'Descendre', off: ei >= n - 1 }, '-', { a: 'p8-type', l: 'Changer de type du bloc…', off: !!p8GardeType(b, e), t: p8GardeType(b, e) || 'Le bloc prend en entier la disposition du type choisi, comme créé par « + bloc » ; chaque ligne reste un élément' } /* (p8-4) un bloc tapé n'a que ses lignes : le clic droit sur une ligne le propose aussi */, '-', { a: 'e-supprimer', l: 'Supprimer l\'élément', off: n <= 1, t: n <= 1 ? 'un bloc garde au moins un élément' : 'Suppr' }]; menuA($('menu'), ev.clientX, ev.clientY, items); $('menu').onclick = ev2 => { const bt = ev2.target.closest('[data-a]'); if (!bt || bt.disabled) return; $('menu').classList.remove('on'); const act = bt.dataset.a; journal('atelier-menu', { di: S.di, bi, ei, action: act }); if (act === 'p8-type') { p8MenuType(bi, ev.clientX, ev.clientY); return; } /* (p8-4) */ if (act === 'e-dupliquer') { b.el.splice(ei + 1, 0, b.el[ei]); p8NotesElement(S.di, bi, ei + 1, 'inserer'); } if (act === 'e-monter') { const t = b.el[ei - 1]; b.el[ei - 1] = b.el[ei]; b.el[ei] = t; p8NotesElement(S.di, bi, ei, 'monter'); } if (act === 'e-descendre') { const t = b.el[ei + 1]; b.el[ei + 1] = b.el[ei]; b.el[ei] = t; p8NotesElement(S.di, bi, ei, 'descendre'); } if (act === 'e-supprimer') { b.el.splice(ei, 1); p8NotesElement(S.di, bi, ei, 'supprimer'); } /* (p8-5c) les notes suivent leur élément */ marquerModif({ di: S.di, bi, ei, action: act }); dr_tout(); }; return; }
  const image = b.t === 'image'; const items = image ? [{ a: 'titre', l: `Image · bloc ${bi + 1}`, off: true }, '-', { a: 'b-supprimer', l: 'Supprimer l\'image' }] : [{ a: 'titre', l: `Bloc ${bi + 1} · ${(b.t || '').toUpperCase()} · ${n} élément${n > 1 ? 's' : ''}`, off: true }, '-', { a: 'p8-type', l: 'Changer de type…', off: !!p8GardeType(b, e), t: p8GardeType(b, e) || 'Le bloc prend en entier la disposition du type choisi, comme créé par « + bloc » ; chaque ligne reste un élément' } /* (p8-4) */, '-', ...(b.t === 'fiche' ? [{ a: 'b-lier', l: b.feuille ? 'Changer la fiche liée…' : 'Lier à une fiche…', t: 'la fiche vit dans une feuille du chapitre (1.7)' }] : []), ...(b.t === 'video' ? [{ a: 'b-reperes', l: 'Repères…', t: 'les repères rendent la vidéo dévoilable comme un bloc (4b.2)' }] : []), { a: 'b-dupliquer', l: 'Dupliquer le bloc', off: b.t !== 'schema' && p8DiapoASchema(e), t: b.t === 'schema' ? 'une diapo n\'a qu\'un schéma : la copie part dans une diapo nouvelle, juste après (même heure, même activité, mêmes notions, la durée partagée), nouvelle identité' : p8DiapoASchema(e) ? 'Cette diapo a son schéma : un second bloc n\'y entre pas — copie ce bloc (Ctrl + C) et colle-le dans la diapo suivante' : 'juste après, nouvelle identité' }, { a: 'b-monter', l: 'Monter', off: bi === 0, t: 'Alt + ↑' }, { a: 'b-descendre', l: 'Descendre', off: bi >= e.blocs.length - 1, t: 'Alt + ↓' }, (b.t === 'schema' ? { a: 'b-taille', l: `Taille : ${b.taille === 'grand' ? 'normal' : '[normal]'} · ${b.taille === 'grand' ? '[grand]' : 'grand'}`, t: 'Un schéma garde ses libellés à 32 et 26 pt pour être lu du fond : il n\'a pas de taille « petit » — ce geste passe de normal à grand, et retour' } : { a: 'b-taille', l: `Taille : ${b.taille === 'petit' ? '[petit]' : 'petit'} · ${!b.taille || b.taille === 'normal' ? '[normal]' : 'normal'} · ${b.taille === 'grand' ? '[grand]' : 'grand'}`, t: 'tourne : petit → normal → grand ; la classe le verra à cette taille' }), '-', { a: 'b-copier', l: 'Copier', t: 'Ctrl + C' }, { a: 'b-couper', l: 'Couper', t: 'Ctrl + X', off: e.blocs.length <= 1 }, { a: 'b-coller', l: 'Coller ici', off: !S.pressePapiers || !!p8GardeColler(S.pressePapiers, e), t: !S.pressePapiers ? 'rien dans le presse-papiers' : p8GardeColler(S.pressePapiers, e) ? p8GardeColler(S.pressePapiers, e) : S.pressePapiers.t === 'schema' && !p8DiapoLibre(e) ? 'un schéma a sa diapo : il part dans une diapo nouvelle, juste après (même heure, même activité, mêmes notions, la durée partagée), nouvelle identité' : 'Ctrl + V — coller donne toujours une nouvelle identité : le bloc est neuf jusqu\'à sa première apparition' }, '-', { a: 'b-couper-diapo', l: 'Couper la diapo ici', off: bi === 0, t: bi === 0 ? 'la diapo se coupe avant un bloc qui n\'est pas le premier' : 'une seconde diapo « (suite) » avec ce bloc et les suivants, même heure, mêmes notions (0.4)' }, { a: 'b-supprimer', l: 'Supprimer le bloc', t: 'confirmation si des réponses d\'élèves y sont accrochées' }];
  menuA($('menu'), ev.clientX, ev.clientY, items); $('menu').onclick = ev2 => { const bt = ev2.target.closest('[data-a]'); if (!bt || bt.disabled) return; $('menu').classList.remove('on'); const act = bt.dataset.a; journal('atelier-menu', { di: S.di, bi, action: act }); if (act === 'p8-type') { p8MenuType(bi, ev.clientX, ev.clientY); return; } /* (p8-4) */ if (act === 'b-lier') { S.lierFiche = bi; choixObjet('fiche'); } if (act === 'b-reperes') { S.editerVideo = bi; choixObjet('video'); } if (act === 'b-dupliquer' && b.t === 'schema') { if (e.role === 'bilan') { toast('Rien ne s\'insère après le bilan.'); return; } const n = p8DiapoApres(S.di, [cloneBloc(b)]); apresTrame({ di: S.di, dupliqueSchema: n.eid }); toast('Schéma dupliqué dans une diapo nouvelle, juste après : « ' + n.act + ' » — une diapo n\'a qu\'un schéma.'); dr_tout(); return; } /* (p8-3) */ if (act === 'b-dupliquer') { e.blocs.splice(bi + 1, 0, cloneBloc(b)); p8NotesBloc(S.di, bi + 1, 'inserer', 1); /* (p8-5c) */ marquerModif({ di: S.di, bi, duplique: true }); dr_tout(); } if (act === 'b-monter') deplacerBloc(bi, -1); if (act === 'b-descendre') deplacerBloc(bi, 1); if (act === 'b-taille') { b.taille = b.t === 'schema' ? (b.taille === 'grand' ? 'normal' : 'grand') /* (p8-3) « petit » grisé pour un schéma */ : b.taille === 'petit' ? 'normal' : (!b.taille || b.taille === 'normal') ? 'grand' : 'petit'; marquerModif({ di: S.di, bi, taille: b.taille }); dr_tout(); } if (act === 'b-copier') { S.pressePapiers = JSON.parse(JSON.stringify(b)); toast('Bloc copié.'); } if (act === 'b-couper') { S.pressePapiers = JSON.parse(JSON.stringify(b)); e.blocs.splice(bi, 1); p8NotesBloc(S.di, bi, 'supprimer'); /* (p8-5c) */ marquerModif({ di: S.di, bi, coupe: true }); dr_tout(); } if (act === 'b-coller' && S.pressePapiers && S.pressePapiers.t === 'schema' && !p8DiapoLibre(e)) { if (e.role === 'bilan') { toast('Rien ne s\'insère après le bilan.'); return; } const n = p8DiapoApres(S.di, [cloneBloc(S.pressePapiers)]); apresTrame({ di: S.di, colleSchema: n.eid }); toast('Schéma collé dans une diapo nouvelle, juste après : « ' + n.act + ' » — un schéma a sa diapo ; celle-ci n\'a pas changé.'); dr_tout(); return; } /* (p8-3) */ if (act === 'b-coller') { e.blocs.splice(bi + 1, 0, cloneBloc(S.pressePapiers)); p8NotesBloc(S.di, bi + 1, 'inserer', 1); /* (p8-5c) */ marquerModif({ di: S.di, bi, colle: true }); dr_tout(); } if (act === 'b-couper-diapo') couperDiapoIci(S.di, bi); if (act === 'b-supprimer') supprimerBloc(bi); }; }

/* ── (p4a) le choix d'objet, les formulaires du contrat, le manque d'objet, « À régler » ── */
const OBJETS = [{ t: 'texte', l: 'Texte', d: 'un titre, quelques lignes — pour dire, pas pour faire' }, { t: 'consigne', l: 'Consigne', d: 'à l\'impératif, des étapes — ce que l\'élève fait' }, { t: 'question', l: 'Question', d: 'jamais vide ; ses réponses attendues à part, jamais dévoilées avec elle' }, { t: 'fiche', l: 'Fiche…', d: 'seulement liée à une fiche d\'une feuille du chapitre — sinon refus' }, { t: 'schema', l: 'Schéma…', d: 'carte, frise, arbre, cycle, tableau — se dévoile élément par élément' }, { t: 'image', l: 'Image…', d: 'une adresse relative dans mjpc-medias, une légende, des marques' }, { t: 'video', l: 'Vidéo…', d: 'un fichier sur ta clé USB, des repères — jamais hébergée' }, { t: 'doc', l: 'Document…', d: 'un document de la séance posé dans le flux : PDF, Word, image à pages, page HTML — tout type, le contrat dit comment il se projette' }, { t: 'page', l: 'Page HTML…', d: 'dernier recours, après un manque déclaré, avec son contrat de pilotage', dernier: true }];

function fermerChoix(){ const z = document.querySelector('.choix-obj'); if (z) z.remove(); }

function choixObjet(type){ fermerChoix(); const e = ecran(); if (!e || e.role === 'fin') return; const z = document.createElement('div'); z.className = 'choix-obj'; z.innerHTML = `<h4><span>QUEL OBJET AJOUTER À LA DIAPO ? — chacun a son contrat (cadrage 4, §3)</span><span class="x" title="Ferme sans rien ajouter">✕</span></h4><div class="dr-g">${OBJETS.filter(o => o.t !== 'texte' /* (p8-4) le texte s'écrit dans la diapo, sous le dernier bloc */).map(o => { const g8 = p8GardeObjet(o.t, e); /* (p8-3) */ return `<div class="dr-c${o.dernier ? ' dernier' : ''}${o.off || g8 ? ' off' : ''}" data-t="${o.t}" title="${dr_esc(g8 ? g8 + '.' : o.d)}"><b>${o.l}</b><span>${dr_esc(g8 || o.d)}</span></div>`; }).join('')}</div><div class="manque">Aucun objet ne convient ? <a data-manque="1">Déclarer un objet manquant</a> — « objet à ajouter à l'éditeur : … » : la ligne reste visible dans « À régler » du chapitre, avec ce qui l'attend (3.3). Personne ne tord un objet pour en faire un autre.</div><div class="form" id="obj-form"></div>`; document.querySelector('.scene').appendChild(z); z.querySelector('.x').onclick = fermerChoix; z.querySelectorAll('.dr-c:not(.off)').forEach(c => c.onclick = () => formulaireObjet(c.dataset.t)); z.querySelector('[data-manque]').onclick = () => formulaireObjet('manque'); if (type) formulaireObjet(type); }

function ajouterBloc(b, focusT){ const e = ecran(); b.bid = nouveauBid(); e.blocs.push(b); marquerModif({ di: S.di, bloc: 'ajout', type: b.t, bi: e.blocs.length - 1 }); fermerChoix(); dr_tout(); setTimeout(() => { const nv = $('mur').querySelector('[data-p="' + (e.blocs.length - 1) + '.t"]'); if (nv && focusT !== false) focaliser(nv); }, 0); }

function formulaireObjet(t){ const f = $('obj-form'); if (!f) return; const e = ecran();
  if (t === 'texte') return ajouterBloc({ t: 'texte', txt: 'Nouveau texte', el: [''] });
  if (t === 'consigne') return ajouterBloc({ t: 'consigne', txt: 'Nouvelle consigne', el: [''] });
  if (t === 'question') { f.innerHTML = `<label>La question (jamais vide)</label><input id="of-q" placeholder="Qu'ont en commun ces cinq tableaux ?"><label>La réponse attendue (à part, jamais dévoilée avec la question)</label><input id="of-r" placeholder="Une nature immense, un homme petit…"><div class="dr-err" id="of-err"></div><div class="dr-ok"><button class="btn or" id="of-ok">Ajouter la question</button></div>`; $('of-ok').onclick = () => { const q = $('of-q').value.trim(), r = $('of-r').value.trim(); if (!q) { $('of-err').textContent = 'Refus : une question n\'est jamais vide.'; return; } if (!r) { $('of-err').textContent = 'Refus : la réponse attendue manque — elle vit à part, c\'est le contrat.'; return; } ajouterBloc({ t: 'question', txt: q, el: [r] }, false); }; $('of-q').focus(); return; }
  if (t === 'fiche') { f.innerHTML = `<label>Quelle fiche ? — une fiche vit dans une feuille du chapitre (1.7) ; le bloc ne fait que la montrer</label>${dr_feuilles()/* E1 : lisait DATA.feuilles */.map(fe => `<div class="fe"><b>Feuille « ${dr_esc(fe.titre)} »</b> · ${fe.fiches.length} fiche${fe.fiches.length > 1 ? 's' : ''}<br>${fe.fiches.map(fi => `<span class="fi" data-fe="${fe.id}" data-fi="${fi.id}" title="Lie cette fiche : le bloc la montre, elle s'agrandit d'un clic en classe">${dr_esc(fi.titre)}</span>`).join('')}</div>`).join('')}<div class="dr-err">Pas de fiche qui convienne ? Écris-la d'abord dans une feuille du chapitre (l'éditeur de feuilles), puis reviens la lier ici. Le bloc n'existe pas sans fiche liée.</div>`; f.querySelectorAll('.fi').forEach(x => x.onclick = () => { const fe = dr_feuilles()/* E1 : lisait DATA.feuilles */.find(z => z.id === x.dataset.fe); const fi = fe.fiches.find(z => z.id === x.dataset.fi); if (S.lierFiche != null) { const b = e.blocs[S.lierFiche]; b.feuille = fe.id; b.fiche = fi.id; b.txt = fi.titre; b.el = fi.el.slice(); S.lierFiche = null; marquerModif({ di: S.di, bi: e.blocs.indexOf(b), lie: fi.id }); fermerChoix(); dr_tout(); } else ajouterBloc({ t: 'fiche', txt: fi.titre, feuille: fe.id, fiche: fi.id, el: fi.el.slice() }, false); }); return; }
  if (t === 'schema') { const CONV = { carte: 'une ligne par branche : « Branche : a, b » — le titre au centre', frise: 'une ligne par repère : « date = événement »', arbre: 'une ligne par nœud ; deux espaces devant pour descendre d\'un niveau', cycle: 'une étape par ligne, dans le sens des aiguilles', tableau: 'une ligne par rangée, les colonnes séparées par « | » ; la première ligne = les en-têtes' }; f.innerHTML = `<label>La forme du schéma — le format existant : une source texte, une ligne par élément ; échelle « plein » par défaut ; se dévoile ligne par ligne</label><select id="of-forme"><option value="carte">carte</option><option value="frise">frise</option><option value="arbre">arbre</option><option value="cycle">cycle</option><option value="tableau">tableau</option></select> <span class="at-note" id="of-conv">${CONV.carte}</span><label>Le titre</label><input id="of-t" placeholder="Les figures de style"><label>La source — une ligne par élément</label><textarea id="of-src" rows="4" style="width:100%;font:inherit;border:1px solid #c99a4e;border-radius:6px;padding:5px 8px;box-sizing:border-box" placeholder="Figures d'analogie : comparaison, métaphore"></textarea><div class="dr-err" id="of-err"></div><div class="dr-ok"><button class="btn or" id="of-ok">Ajouter le schéma</button></div>`; $('of-forme').onchange = () => { $('of-conv').textContent = CONV[$('of-forme').value]; }; $('of-ok').onclick = () => { const tt = $('of-t').value.trim(); const src = $('of-src').value.replace(/\r/g, ''); const lignes = src.split('\n').map(x => x.replace(/\s+$/, '')).filter(x => x.trim()); if (!tt) { $('of-err').textContent = 'Refus : un schéma a un titre.'; return; } if (!lignes.length) { $('of-err').textContent = 'Refus : un schéma a au moins un élément (une ligne).'; return; } p8PoserSchema({ t: 'schema', txt: tt, forme: $('of-forme').value, echelle: 'plein', src: lignes.join('\n'), el: lignes.map(x => x.trim()), devoilerTout: false /* (p8-2) décision 6 ter : créé par « Schéma… », il part « Un à un » */ }); /* (p8-3) décision 1 : sur une diapo qui a déjà du contenu, il part dans une diapo nouvelle, juste après */ }; return; }
  if (t === 'image') { f.innerHTML = `<label>L'adresse dans mjpc-medias — relative (jamais complète)</label><input id="of-src" placeholder="poesie-peinture-xixe/tableau-6.jpg"><label>La légende</label><input id="of-lg" placeholder="Le Radeau de la Méduse, Géricault, 1819"><div class="dr-err" id="of-err"></div><div class="dr-ok"><button class="btn or" id="of-ok">Ajouter l'image</button></div>`; $('of-ok').onclick = () => { const src = $('of-src').value.trim(), lg = $('of-lg').value.trim(); if (!src) { $('of-err').textContent = 'Refus : une image a une adresse.'; return; } if (/^(https?:)?\/\//i.test(src) || /^[a-z]:\\/i.test(src)) { $('of-err').textContent = 'Refus : l\'adresse doit être relative dans mjpc-medias, jamais complète (3.2).'; return; } ajouterBloc({ t: 'image', txt: lg, ref: 'https://siteflow-io.github.io/mjpc-medias/' + src.replace(/^\/+/, '') }, false); }; return; }
  if (t === 'page') { const manques = (S.objetsManquants || []).filter(m => m.si === S.si); f.innerHTML = `<label>Une page HTML ne se fait que si aucun objet ne convient, après un manque déclaré, et sur ton mot (4.1)</label>${manques.length ? `<div class="dr-err" style="color:#1a7a3e">Manque déclaré : ${manques.map(m => '« ' + dr_esc(m.texte) + ' »').join(', ')}</div>` : '<div class="err">Aucun manque d\'objet déclaré dans ce chapitre : déclare-le d\'abord, ou attends l\'objet (un mandat court sur l\'éditeur).</div>'}<label>Le fichier de la page</label><input id="of-src" placeholder="placer-les-poetes.html" ${manques.length ? '' : 'disabled'}><label>Le titre</label><input id="of-t" placeholder="Placer les poètes" ${manques.length ? '' : 'disabled'}><label><input type="checkbox" id="of-contrat" style="width:auto" ${manques.length ? '' : 'disabled'}> La page porte son contrat de pilotage (elle annonce ses étapes, reçoit suivante / précédente, répond où elle en est — 4.2)</label><div class="dr-err" id="of-err"></div><div class="dr-ok"><button class="btn or" id="of-ok" ${manques.length ? '' : 'disabled'}>Ajouter la page</button></div>`; if (manques.length) $('of-ok').onclick = () => { const src = $('of-src').value.trim(), tt = $('of-t').value.trim(); const contrat = $('of-contrat').checked; if (!src || !tt) { $('of-err').textContent = 'Refus : un fichier et un titre.'; return; } ajouterBloc({ t: 'page', txt: tt, src, contrat, etapes: contrat ? 3 : null }, false); if (!contrat) toast('Page sans contrat de pilotage : elle sera jouée comme une image ; « À régler » porte le texte pour l\'instance (4.3).'); }; return; }
  if (t === 'video') { const b = S.editerVideo != null ? e.blocs[S.editerVideo] : null; const cle = S.cleDossier; const reps = b ? (b.reperes || []).slice() : [{ t: 0, l: '' }]; const mmss = t => Math.floor(t / 60) + ':' + String(t % 60).padStart(2, '0'); const lignes = () => reps.map((r, k) => `<div class="rl" style="display:flex;gap:8px;margin:3px 0"><input style="width:90px" data-rt="${k}" value="${mmss(r.t)}" title="m:ss"><input data-rl="${k}" value="${dr_esc(r.l)}" placeholder="le libellé du repère"><button class="btn" data-rx="${k}" style="padding:2px 8px" title="Retire ce repère">✕</button></div>`).join('');
    const dessiner = () => { f.innerHTML = `<label>Le fichier sur ta clé USB — jamais hébergé (4b.1) : désigne le dossier de la clé une fois, le site retient le nom du fichier et le dossier, jamais un chemin de disque</label><div style="display:flex;gap:8px;align-items:center"><button class="btn" id="of-cle" title="Une fenêtre du navigateur : tu choisis le dossier de la clé, une fois (simulé dans la maquette)">Désigner le dossier de la clé…</button><span id="of-cle-etat" style="color:${cle ? '#1a7a3e' : '#b3261e'}">${cle ? '✔ dossier « ' + dr_esc(cle.nom) + ' » désigné sur cet ordi portable · ' + cle.fichiers.length + ' fichiers' : 'aucun dossier désigné'}</span></div>${cle ? `<div class="fe" style="margin-top:6px">${cle.fichiers.map(x => `<span class="fi ${S._ofFichier === x.nom ? 'on' : ''}" data-f="${dr_esc(x.nom)}" data-d="${x.duree}" style="${S._ofFichier === x.nom ? 'background:#fff2c7' : ''}">${dr_esc(x.nom)} · ${mmss(x.duree)}</span>`).join('')}</div>` : ''}<label>La légende</label><input id="of-lg" value="${dr_esc(b ? b.txt : (S._ofLg || ''))}" placeholder="Le Radeau de la Méduse, Géricault — extrait commenté"><label>Les repères — posés en préparation, ils rendent la vidéo dévoilable comme un bloc : ▶ lance jusqu'au repère suivant et s'arrête, ◀ revient au précédent (4b.2)</label><div class="fe" id="of-reps">${lignes()}<button class="btn" id="of-plus" style="font-size:.85rem">+ repère</button></div><div class="dr-err" id="of-err" style="color:#6a5a48">Sans repère, la vidéo est acceptée mais signalée dans « Sur la forme » : ▶ lance / met en pause, rien ne se dévoile par étapes (4b.5).</div><div class="dr-ok"><button class="btn or" id="of-ok">${b ? 'Enregistrer les repères' : 'Ajouter la vidéo'}</button></div>`;
      $('of-cle').onclick = () => { S.cleDossier = { nom: 'MJPC-VIDEOS', fichiers: [{ nom: 'le-radeau.mp4', duree: 245 }, { nom: 'hernani-acte1.mp4', duree: 760 }, { nom: 'lamartine-le-lac.mp4', duree: 190 }] }; journal('atelier-cle-designee', { dossier: 'MJPC-VIDEOS' }); S._ofLg = $('of-lg').value; formulaireObjet('video'); }; f.querySelectorAll('[data-f]').forEach(x => x.onclick = () => { S._ofFichier = x.dataset.f; S._ofDuree = +x.dataset.d; S._ofLg = $('of-lg').value; formulaireObjet('video'); }); const lire = () => { f.querySelectorAll('[data-rt]').forEach(i => { const k = +i.dataset.rt; const m = /^(\d+):(\d{1,2})$/.exec(i.value.trim()); reps[k].t = m ? +m[1] * 60 + +m[2] : reps[k].t; }); f.querySelectorAll('[data-rl]').forEach(i => { reps[+i.dataset.rl].l = i.value; }); }; $('of-plus').onclick = () => { lire(); reps.push({ t: reps.length ? reps[reps.length - 1].t + 60 : 0, l: '' }); S._ofLg = $('of-lg').value; dessiner(); }; f.querySelectorAll('[data-rx]').forEach(x => x.onclick = () => { lire(); reps.splice(+x.dataset.rx, 1); S._ofLg = $('of-lg').value; dessiner(); });
      $('of-ok').onclick = () => { lire(); const lg = $('of-lg').value.trim(); const propres = reps.filter(r => r.l.trim()).sort((a, b2) => a.t - b2.t); if (b) { b.reperes = propres; b.txt = lg || b.txt; S.editerVideo = null; marquerModif({ di: S.di, bi: e.blocs.indexOf(b), reperes: propres.length }); fermerChoix(); dr_tout(); return; } if (!S.cleDossier) { $('of-err').innerHTML = '<span style="color:#b3261e">Refus : désigne d\'abord le dossier de la clé (une fois).</span>'; return; } if (!S._ofFichier) { $('of-err').innerHTML = '<span style="color:#b3261e">Refus : choisis le fichier sur la clé.</span>'; return; } if (!lg) { $('of-err').innerHTML = '<span style="color:#b3261e">Refus : une vidéo a une légende.</span>'; return; } ajouterBloc({ t: 'video', txt: lg, fichier: S._ofFichier, dossier: S.cleDossier.nom, duree: S._ofDuree || 0, reperes: propres }, false); S._ofFichier = null; S._ofLg = ''; if (!propres.length) toast('Vidéo sans repère : acceptée, signalée dans « Sur la forme » — ▶ lance / met en pause.'); }; }; dessiner(); return; }
  if (t === 'doc') { const docs = dr_documents()/* E1 : lisait DATA.documents */[String(S.si)] = dr_documents()/* E1 : lisait DATA.documents */[String(S.si)] || []; const typeDe = nom => { const ext = (nom.split('.').pop() || '').toLowerCase(); return ext === 'pdf' ? 'pdf' : ['jpg', 'jpeg', 'png', 'webp'].includes(ext) ? 'image' : ['html', 'htm'].includes(ext) ? 'html' : ext === 'docx' ? 'docx' : 'autre'; }; const CONTRAT = { pdf: 'ses pages, aux flèches', image: 'ses pages, aux flèches', html: 'ses étapes (avec contrat, 4.2)', docx: 'lu par le site (bibliothèque libre) et projeté comme des pages — si la lecture échoue, convertis-le en PDF', autre: 'non projetable tel quel : convertis-le en PDF' };
    f.innerHTML = `<label>Un document de la séance, posé dans le flux à sa place (4 ter) — ${docs.length ? 'choisis-en un déjà joint, ou joins-en un nouveau' : 'joins-en un'}</label>${docs.length ? `<div class="fe">${docs.map(d => `<span class="fi" data-doc="${dr_esc(d.id)}" title="${dr_esc(d.type)} · ${d.pages ? d.pages + ' pages' : (d.etapes || 0) + ' étapes'}">${dr_esc(d.titre)} · ${dr_esc(d.type)}</span>`).join('')}</div>` : ''}<label>Joindre un nouveau document — le nom du fichier (le type se lit dans l'extension : .pdf, .docx, .jpg, .html… tout type est accepté, le contrat dit comment il se projette)</label><input id="of-fic" placeholder="fiche-methode-decrire-une-image.pdf"><label>Le titre</label><input id="of-t" placeholder="Fiche méthode : décrire une image"><label>Pages (PDF, image, Word) ou étapes (page HTML)</label><input id="of-n" type="number" min="1" value="3" style="width:100px"><div class="dr-err" id="of-err"></div><div class="dr-ok"><button class="btn or" id="of-ok">Joindre et poser dans la diapo</button></div>`;
    f.querySelectorAll('[data-doc]').forEach(x => x.onclick = () => ajouterBloc({ t: 'doc', doc: x.dataset.doc, txt: (docs.find(d => d.id === x.dataset.doc) || {}).titre || '' }, false)); $('of-ok').onclick = () => { const fic = $('of-fic').value.trim(), tt = $('of-t').value.trim(), n = +$('of-n').value || 1; if (!fic || !tt) { $('of-err').textContent = 'Refus : un fichier et un titre.'; return; } const type = typeDe(fic); const d = { id: 'doc-' + Date.now().toString(36), titre: tt, fichier: fic, type, pages: type === 'html' ? undefined : n, etapes: type === 'html' ? n : undefined, contrat: type === 'html' ? true : undefined }; docs.push(d); journal('atelier-document-joint', { id: d.id, genre: type }); ajouterBloc({ t: 'doc', doc: d.id, txt: tt }, false); if (type === 'docx') toast('Document Word joint : ' + CONTRAT.docx + '.'); if (type === 'autre') toast('Document « .' + fic.split('.').pop() + ' » joint : ' + CONTRAT.autre + ' — signalé dans « Sur la forme ».'); }; return; }
  if (t === 'manque') { f.innerHTML = `<label>Quel objet manque à l'éditeur ? — dis-le en un mot ou deux : la ligne restera visible dans « À régler », avec le chapitre qui l'attend (3.3)</label><input id="of-m" placeholder="un tableau à deux colonnes remplissable en classe"><div class="dr-err" id="of-err"></div><div class="dr-ok"><button class="btn or" id="of-ok">Déclarer le manque</button></div>`; $('of-ok').onclick = () => { const m = $('of-m').value.trim(); if (!m) { $('of-err').textContent = 'Dis ce qui manque.'; return; } S.objetsManquants = S.objetsManquants || []; S.objetsManquants.push({ si: S.si, di: S.di, texte: m, t: now() }); journal('atelier-objet-manquant', { di: S.di, texte: m }); marquerModif({ di: S.di, manque: m }); fermerChoix(); toast('Objet manquant déclaré : « ' + m + ' » — visible dans « À régler » ; ce chapitre l\'attend.'); dr_tout(); }; $('of-m').focus(); return; } }

function alertesForme(){ /* tout ce qui peut casser en classe, chapitre entier : la liste de « À régler » (6.1), avec le texte prêt à copier */ const E = seance().ecrans; const out = []; E.forEach((e, i) => (e.blocs || []).forEach((b, bi) => { const ou = `diapo ${i + 1} · « ${e.act} » · bloc ${bi + 1}`; const TYPES = ['consigne', 'texte', 'question', 'fiche', 'schema', 'image', 'video', 'page', 'doc', 'cahier']; /* (p8-3c) le cahier de textes a son rendu */ if (!TYPES.includes(b.t)) out.push({ di: i, bi, k: 'nonlisible', l: `Objet non lisible « ${b.t} »`, ou, faire: 'déclare un objet manquant, ou remplace-le par un objet connu (3.1)', copier: `Dans le chapitre « ${seance().titre} », ${ou} : l'objet « ${b.t} » n'est pas dans le contrat de l'éditeur MJPC. Remplace-le par un objet du contrat (texte, consigne, question, fiche, schéma, image, vidéo, page avec contrat) ou déclare-le comme objet manquant.` }); if (b.t === 'fiche' && !b.feuille) out.push({ di: i, bi, k: 'fiche', l: `Fiche « ${b.txt || ''} » non liée à une feuille`, ou, faire: 'lie-la à une fiche d\'une feuille du chapitre (clic droit → Lier à une fiche…), sinon le bloc ne s\'affiche pas (1.7)', copier: `Dans le chapitre « ${seance().titre} », ${ou} : la fiche « ${b.txt || ''} » doit être écrite dans une feuille du chapitre et liée par son identifiant (feuille + fiche).` }); if (b.t === 'page' && !b.contrat) out.push({ di: i, bi, k: 'page', l: `Page HTML « ${b.txt || ''} » sans contrat de pilotage`, ou, faire: 'ajoute le contrat (la page annonce ses étapes, reçoit suivante / précédente, répond où elle en est — 4.2) ; jouée comme une image en attendant', copier: `Page « ${b.src || ''}» (${ou}) : ajoute le contrat de pilotage MJPC — au chargement, envoie postMessage({type:'mjpc-page', etapes:n}) ; réponds à {type:'mjpc-etape', aller:k} en affichant l'étape k et en renvoyant {type:'mjpc-ou', etape:k}.` }); if (b.t === 'video' && !(b.reperes || []).length) out.push({ di: i, bi, k: 'video', l: `Vidéo « ${b.txt || ''} » sans repère`, ou, faire: 'acceptée ; ▶ lance / met en pause, rien ne se dévoile par étapes — pose des repères (clic droit → Repères…) (4b.5)', copier: `Vidéo « ${b.fichier || ''} » (${ou}) : ajoute des repères (temps + libellé) dans la trame.` }); if (b.t === 'doc') { const d = (dr_documents()/* E1 : lisait DATA.documents */[String(S.si)] || []).find(x => x.id === b.doc); if (!d) out.push({ di: i, bi, k: 'doc', l: `Document introuvable dans la séance`, ou, faire: 'rejoins le document ou retire le bloc', copier: `Bloc document (${ou}) : l'identifiant « ${b.doc} » ne correspond à aucun document de la séance.` }); else if (d.type === 'autre') out.push({ di: i, bi, k: 'doc', l: `Document « ${d.titre} » (.${(d.fichier || '').split('.').pop()}) non projetable tel quel`, ou, faire: 'convertis-le en PDF (4 ter)', copier: `Document « ${d.fichier || d.titre} » (${ou}) : à convertir en PDF pour être projeté.` }); else if (d.type === 'docx') out.push({ di: i, bi, k: 'doc', l: `Document Word « ${d.titre} » — lu par le site`, ou, faire: 'si la lecture échoue en classe, convertis-le en PDF (4 ter)', copier: `Document Word « ${d.fichier || d.titre} » (${ou}) : lu par une bibliothèque libre ; en cas d'échec, PDF.` }); } if (b.t === 'image' && b.ref && !/mjpc-medias/.test(b.ref)) out.push({ di: i, bi, k: 'image', l: `Image « ${b.txt || ''} » hors de mjpc-medias`, ou, faire: 'range-la dans mjpc-medias et donne son adresse relative (3.2)', copier: `Image « ${b.ref} » (${ou}) : à ranger dans mjpc-medias, adresse relative.` }); })); E.forEach((e, i) => (e.blocs || []).forEach((b, bi) => { if (b.t === 'video' && b.fichier) { const cle = S.cleDossier; const ok = cle && cle.fichiers.some(f => f.nom === b.fichier); if (!ok) out.push({ di: i, bi, k: 'video-fichier', l: `Vidéo « ${b.txt || b.fichier} » : fichier non atteignable — « ${b.fichier} » ${cle ? 'n\'est pas dans le dossier « ' + cle.nom + ' » désigné' : 'et aucun dossier de clé n\'est désigné'}`, ou: `diapo ${i + 1} · « ${e.act} » · bloc ${bi + 1}`, faire: 'remets le fichier sur la clé, ou redésigne le dossier (« + vidéo… » → Désigner le dossier de la clé…) ; en classe, la diapo passerait toute seule et le récit dirait « qu\'on regardera à la prochaine séance » (4b.4)', copier: `Vidéo « ${b.fichier} » (${e.act}) : fichier absent du dossier de la clé.` }); } })); E.forEach((e2, i2) => { if (!p8AvecTexte(e2) || e2.role === 'fin') return; const bi2 = e2.blocs.findIndex(b => b.t === 'schema'); out.push({ di: i2, bi: bi2, k: 'texte', l: 'Schéma avec du texte : donne-lui sa diapo — clic droit sur le bloc → Couper la diapo ici', ou: `diapo ${i2 + 1} · « ${e2.act} » · bloc ${bi2 + 1}`, faire: 'un schéma par diapo : ' + P8_UNE + ' (cadrage 4, 3.2)', copier: `Diapo « ${e2.act} » : le schéma « ${e2.blocs[bi2].txt || ''} » doit avoir sa diapo (son titre, le schéma, au plus une consigne d'une ligne).` }); }); /* (p8-3) la trame d'avant la règle */ if (S.atelier && !S.repetition) { E.forEach((e2, i2) => (e2.blocs || []).forEach((b2, bi2) => { if (b2.t !== 'schema' || e2.role === 'fin') return; const r = (p8MesureDiapo(i2).blocs || {})[bi2]; if (!r || !r.total) return; out.push({ di: i2, bi: bi2, k: 'dense', l: `Schéma « ${b2.txt || ''} » : il ne tient pas lisible — coupe-le : clic droit sur une famille → Couper le schéma ici`, ou: `diapo ${i2 + 1} · « ${e2.act} » · bloc ${bi2 + 1}`, faire: `mesuré au tableau : ${r.chevauchements} chevauchement${r.chevauchements > 1 ? 's' : ''}, ${r.horsCadre} hors du cadre visible, ${r.traits} trait${r.traits > 1 ? 's' : ''} à travers un mot, ${r.deuxLignes} libellé${r.deuxLignes > 1 ? 's' : ''} sur deux lignes, ${r.sousPlancher} police${r.sousPlancher > 1 ? 's' : ''} sous 26 pt — la police ne descend jamais sous 26 pt : c'est le schéma qu'on coupe`, copier: `Schéma « ${b2.txt || ''} » (${e2.act}) : il ne tient pas lisible au tableau (${r.total} défaut${r.total > 1 ? 's' : ''} de lecture) ; à couper en deux schémas, chacun sur sa diapo.` }); })); const c = document.querySelector('#mur .corpsd'); const pages = S.pagesCourantes ? S.pagesCourantes.length : 1; if ((c && !c.classList.contains('plein-img') && c.scrollHeight > c.clientHeight + 2) || pages > 1) { const e = E[S.di]; const px = policePx ? Math.round(policePx()) : 0; out.push({ di: S.di, k: 'pleine', l: `Diapo trop pleine : le texte passe sous le plancher lisible du fond${px ? ' (' + px + ' px de police)' : ''}`, ou: `diapo ${S.di + 1} · « ${e.act} »`, faire: 'coupe la diapo : clic droit sur le bloc ou l\'étape où couper → « Couper la diapo ici » (une seconde diapo « (suite) », même heure, mêmes notions) ; ou retire un bloc ; ou mets-en un en « petit ». Le site ne coupe jamais seul (0.4)', copier: `Diapo « ${e.act} » : trop pleine pour le tableau, à couper en deux.` }); } } E.forEach((e, i) => { if (!e.role && !actDe(e)) out.push({ di: i, k: 'activite', l: `Diapo « ${e.act} » sans numéro d'activité`, ou: `diapo ${i + 1}`, faire: 'rattache-la à une activité (la carte « Ce que la diapo déclare ») — un chapitre dont les activités ne sont pas toutes numérotées est refusé à l\'import (3.2 bis)', copier: `Diapo « ${e.act} » (chapitre « ${seance().titre} ») : à rattacher à une activité numérotée (numéro continu sur le chapitre).` }); }); (S.objetsManquants || []).filter(m => m.si === S.si).forEach(m => out.push({ di: m.di, k: 'manque', l: `Objet à ajouter à l'éditeur : « ${m.texte} »`, ou: `diapo ${m.di + 1} · « ${E[m.di] ? E[m.di].act : ''} »`, faire: 'un mandat court sur l\'éditeur, ou une page HTML pour cette fois, sur ton mot (4.1)', copier: `Mandat : ajouter à l'éditeur MJPC l'objet « ${m.texte} » (attendu par le chapitre « ${seance().titre} », ${E[m.di] ? E[m.di].act : ''}) avec son contrat aux trois endroits : prompt d'injection, validation à l'import, formulaire de l'éditeur.` })); return out; }

function p8MesureDiapo(i){ /* (p8-2) la mesure d'une diapo du chapitre, rendue telle que la classe la voit (hors de l'écran, à la taille du tableau du pilote) */ const E = seance().ecrans; const e = E[i]; const m0 = $('mur'); const W = m0.clientWidth || 1096, H = m0.clientHeight || 616; const st = parDiapo[K(i)] || {}; const cle0 = JSON.stringify([S.si, e.eid, e.blocs, S.taille, W, H, st.reps || {}, st.textes || {}]); window.P8_ALERTES = window.P8_ALERTES || {}; if (P8_ALERTES[cle0]) return P8_ALERTES[cle0]; if (Object.keys(P8_ALERTES).length > 200) window.P8_ALERTES = {}; let z = $('p8-banc'); if (!z) { z = document.createElement('div'); z.id = 'p8-banc'; z.setAttribute('aria-hidden', 'true'); dr_zone()/* E1 : lisait document.body */.appendChild(z); } z.className = 'mur tableau'; z.style.cssText = 'position:fixed;left:-20000px;top:0;opacity:0;pointer-events:none;width:' + W + 'px;height:' + H + 'px'; rendre(z, { si: S.si, di: i, nDev: elements(e).length, lum: [], ecr: [], taille: S.taille, page: 0, reps: st.reps || {}, tailles: st.tailles || {}, textes: st.textes || {}, fsBloc: {}, pilote: false }); const r = p8MesureLisible(z); P8_ALERTES[cle0] = r; return r; }

function ouvrirARegler(){ const al = alertesForme(); const z = document.createElement('div'); z.className = 'choix-obj'; z.innerHTML = `<h4><span>À RÉGLER — ${al.length ? al.length + ' chose' + (al.length > 1 ? 's' : '') + ' qui peu' + (al.length > 1 ? 'vent' : 't') + ' casser en classe, dans ce chapitre' : 'rien : ce chapitre ne cassera pas en classe'} (cadrage 4, 6.1)</span><span class="x">✕</span></h4>${al.map((a, k) => `<div class="fe"><b>${dr_esc(a.l)}</b> — ${dr_esc(a.ou)}<br><span style="color:#6a5a48;font-size:.85rem">${dr_esc(a.faire)}</span><br><button class="btn" data-ouvrir="${a.di}" data-k="${a.k}" style="font-size:.8rem;margin-top:4px">Ouvrir la diapo</button> <button class="btn" data-copier="${k}" style="font-size:.8rem;margin-top:4px" title="Le texte prêt à copier pour l'instance (4.3)">Copier le texte pour l'instance</button></div>`).join('')}`; document.querySelector('.scene').appendChild(z); z.querySelector('.x').onclick = fermerChoix; z.querySelectorAll('[data-ouvrir]').forEach(b => b.onclick = () => { S.di = +b.dataset.ouvrir; S.page = null; const a = al.find(x => x.di === S.di && x.k === b.dataset.k) || al.find(x => x.di === S.di); if (a && a.k === 'activite') { S.declareOuverte = true; S.declareEid = seance().ecrans[S.di].eid; S.declareLigne = 'l\'activité — rattache la diapo à une activité numérotée'; } fermerChoix(); dr_tout(); }); z.querySelectorAll('[data-copier]').forEach(b => b.onclick = () => { const t = al[+b.dataset.copier].copier; S.dernierCopie = t; if (navigator.clipboard) navigator.clipboard.writeText(t).catch(() => {}); journal('atelier-copie-instance', { k: al[+b.dataset.copier].k }); toast('Copié : « ' + t.slice(0, 80) + '… »'); }); }

/* ── (p5) la carte « Ce que la diapo déclare » qui s'écrit ── */
function nouvelleActivite(titre){ const acts = dr_activites()/* E1 : lisait DATA.activites */[String(S.si)] = dr_activites()/* E1 : lisait DATA.activites */[String(S.si)] || []; const num = acts.reduce((m, z) => Math.max(m, parseInt(z.num) || 0), 0) + 1; const a = { id: 'a' + S.si + '-n' + Date.now().toString(36), num, titre: titre || 'Activité ' + num, diapos: [] }; acts.push(a); journal('atelier-activite', { id: a.id, num }); return a; }

function renumeroter(){ const E = seance().ecrans; const acts = dr_activites()/* E1 : lisait DATA.activites */[String(S.si)] || []; let n = 0; const vus = new Set(); E.forEach(e => { const a = actDe(e); if (a && !vus.has(a.id)) { vus.add(a.id); a.num = ++n; } }); acts.filter(a => !vus.has(a.id)).forEach(a => { a.num = ++n; }); marquerModif({ renumerote: n }); dr_tout(); }

function choixNotion(cb){ fermerChoix(); const E = seance().ecrans; const z = document.createElement('div'); z.className = 'choix-obj'; const vues = {}; const chap = [...new Set(E.flatMap(e => (e.comp || []).concat(e.remob || [])))]; chap.forEach(id => { vues[id] = 1; }); z.innerHTML = `<h4><span>QUELLE NOTION ? — celles du chapitre d'abord, puis tout le programme par famille</span><span class="x">✕</span></h4><div class="form"><div class="fe">${chap.map(id => `<span class="fi" data-n="${dr_esc(id)}">${dr_esc(libNotion(id))}</span>`).join('') || '<i>aucune notion dans le chapitre</i>'}</div><a href="#" id="cn-tout" style="font-size:.85rem">tout le programme…</a><div id="cn-tout-z" style="display:none;margin-top:4px"></div></div>`; document.querySelector('.scene').appendChild(z); z.querySelector('.x').onclick = fermerChoix; const brancher = () => z.querySelectorAll('[data-n]').forEach(x => { if (x._ok) return; x._ok = true; x.onclick = () => { fermerChoix(); cb(x.dataset.n); }; }); brancher(); $('cn-tout').onclick = ev => { ev.preventDefault(); ev.target.style.display = 'none'; const z2 = $('cn-tout-z'); z2.style.display = 'block'; z2.innerHTML = dr_taxo()/* E1 : lisait DATA.taxo */.map(d => d.familles.map(f => { const ns = f.notions.filter(n => !vues[n.id]); return ns.length ? `<details><summary style="cursor:pointer;color:#6a5a48">${dr_esc(d.nom || d.domaine || '')} · ${dr_esc(f.nom || f.famille || '')} (${ns.length})</summary>${ns.map(n => `<span class="fi" data-n="${n.id}">${dr_esc(n.prof || n.eleve || n.id)}</span>`).join('')}</details>` : ''; }).join('')).join(''); brancher(); }; }

function familleDe(id){ return String(id).replace(/-?\d+$/, ''); }

function proposerRemob(){ const E = seance().ecrans; const e = ecran(); const i = S.di; const fam = new Set((e.comp || []).map(familleDe)); const avant = E.slice(0, i).flatMap(z => z.comp || []); const prop = [...new Set(avant.filter(id => fam.has(familleDe(id)) && !(e.comp || []).includes(id) && !(e.remob || []).includes(id)))]; if (!prop.length) { toast('Rien à proposer : aucune notion de la même famille travaillée plus tôt dans le chapitre.'); return; } e.remob = (e.remob || []).concat(prop); marquerModif({ di: i, remob: prop }); toast('Remobilise, proposition par défaut : ' + prop.map(libNotion).join(', ')); dr_tout(); }

function passerEnHeure(h){ const E = seance().ecrans; const e = ecran(); const rf = roleFixe(e); if (rf) return alert(rf + ' ne change pas d\'heure.'); const i = S.di; E.splice(i, 1); let pos; if (h > e.heure) { pos = E.findIndex(z => z.heure === h); if (pos < 0) pos = E.length; if (E[pos] && E[pos].role === 'reactivation') pos++; } else { pos = E.length; for (let q = E.length - 1; q >= 0; q--) { if (E[q].heure === h && E[q].role !== 'fin') { pos = q + 1; break; } } } const anc = e.heure; e.heure = h; E.splice(pos, 0, e); apresTrame({ di: i, passe: e.eid, de: anc, vers: h }); S.di = indexDe(e.eid); toast('Diapo passée en H' + h + ' (elle était en H' + anc + ') — le compte des heures est recalculé.'); dr_tout(); }

function brancherDeclare(da){ const e = ecran(); if (!e) return; da.querySelectorAll('[data-declare]').forEach(b => b.onclick = () => { if (b.dataset.declare === 'ouvrir') { S.declareOuverte = true; S.declareEid = e.eid; } else { S.declareOuverte = false; S.declareLigne = null; } dr_tout(); }); da.querySelectorAll('[data-pli]').forEach(h => h.onclick = () => { S.plis = S.plis || {}; const k = h.dataset.pli; S.plis[k] = S.plis[k] === false ? true : false; dr_tout(); }); const E = seance().ecrans; const sel = da.querySelector('#dc-act'); if (sel) sel.onchange = () => { const v = sel.value; if (v === '+') { const t = prompt('Le titre de la nouvelle activité :'); if (!t) { dr_tout(); return; } const a = nouvelleActivite(t); e.actId = a.id; } else e.actId = v || null; delete e.__num; reindexer(); marquerModif({ di: S.di, activite: e.actId }); dr_tout(); };
  const lie = (id, quoi) => { const el = da.querySelector('#' + id); if (!el) return; el.onblur = () => quoi(el.textContent.trim()); el.onkeydown = ev => { if (ev.key === 'Enter') { ev.preventDefault(); el.blur(); } ev.stopPropagation(); }; };
  lie('dc-atitre', t => { const a = actDe(e); if (a && t && a.titre !== t) { a.titre = t; marquerModif({ di: S.di, titreActivite: t }); dr_tout(); } }); lie('dc-titre', t => { if (t && e.act !== t) { e.act = t; marquerModif({ di: S.di, titre: t }); dr_tout(); } }); lie('dc-leg', t => { const leg = {}; t.split('·').map(x => x.trim()).filter(Boolean).forEach(x => { const m = /^(\S+)\s*=\s*(.+)$/.exec(x); if (m) leg[m[1]] = m[2]; }); if (Object.keys(leg).length) e.legende = leg; else delete e.legende; marquerModif({ di: S.di, legende: leg }); dr_tout(); }); lie('dc-tp', t => { dr_travail()/* E1 : lisait DATA.travailPrevu = DATA.travailPrevu || {} — le socle tient l'objet */; const k = S.si + '|' + e.heure; if ((dr_travail()/* E1 : lisait DATA.travailPrevu */[k] || '') !== t) { if (t) dr_travail()/* E1 : lisait DATA.travailPrevu */[k] = t; else delete dr_travail()/* E1 : lisait DATA.travailPrevu */[k]; marquerModif({ heure: e.heure, travailPrevu: t }); dr_tout(); } });
  const dur = da.querySelector('#dc-dur'); if (dur) dur.onchange = () => { const v = Math.max(1, +dur.value || 1); if (v !== e.dur) { e.dur = v; if (S.durees && actDe(e)) delete S.durees[actDe(e).id]; marquerModif({ di: S.di, dur: v }); dr_tout(); } };
  const role = da.querySelector('#dc-role'); if (role) role.onchange = () => { const v = role.value || null; if (v === 'bilan' && E.some((z, i) => z.role === 'bilan' && i !== S.di)) { alert('Le bilan est unique : une seule diapo « bilan » par séance.'); dr_tout(); return; } if (v === 'reactivation') { const o = ordreHeure(e.heure).filter(i => !retiree(E[i])); const deja = E.some((z, i) => z.role === 'reactivation' && z.heure === e.heure && i !== S.di); if (deja) { alert('Il y a déjà une réactivation dans cette heure : elle est unique.'); dr_tout(); return; } if (o[0] !== S.di) { alert('La réactivation est la première de son heure : monte d\'abord la diapo en tête de l\'heure.'); dr_tout(); return; } } e.role = v; marquerModif({ di: S.di, role: v }); dr_tout(); };
  da.querySelectorAll('[data-heure]').forEach(b => b.onclick = () => passerEnHeure(+b.dataset.heure)); da.querySelectorAll('[data-retire]').forEach(b => b.onclick = () => { const q = b.dataset.retire; e[q] = (e[q] || []).filter(id => id !== b.dataset.id); marquerModif({ di: S.di, [q]: e[q] }); dr_tout(); }); da.querySelectorAll('[data-plus]').forEach(b => b.onclick = () => choixNotion(id => { const q = b.dataset.plus; e[q] = e[q] || []; if (!e[q].includes(id)) e[q].push(id); marquerModif({ di: S.di, [q]: e[q] }); dr_tout(); })); const pr = da.querySelector('[data-proposer]'); if (pr) pr.onclick = proposerRemob; const na = da.querySelector('[data-nouvelle-act]'); if (na) na.onclick = () => { const t = prompt('Le titre de la nouvelle activité :'); if (!t) return; const a = nouvelleActivite(t); if (!actDe(e) && !e.role) e.actId = a.id; reindexer(); marquerModif({ activite: a.id }); dr_tout(); }; const rn = da.querySelector('[data-renum]'); if (rn) rn.onclick = renumeroter; }

/* ── (p6) la répétition ── */
function lancerRepetition(){ if (S.repetition) return; const clone = x => JSON.parse(JSON.stringify(x)); S.repSnap = { S: clone(Object.fromEntries(Object.entries(S).filter(([k, v]) => !k.startsWith('_') && k !== 'repSnap' && typeof v !== 'function'))), vuMax: clone(vuMax), parDiapo: clone(parDiapo), Jlen: J.length, di: S.di, ecrans: clone(dr_seances()/* E1 : lisait DATA.seances */[S.si].ecrans) /* (p8-4) la séance : ses diapos et leurs blocs */ }; S.repetition = true; S.repT0 = Date.now(); S.atelier = false; document.body.classList.remove('vue-atelier'); $('ong-atelier').classList.remove('on'); voir('pilotage'); document.querySelector('.haut').classList.add('p8-rep'); $('rep-chrono').textContent = '00:00'; $('rep-ou').textContent = ''; $('rep-stop').onclick = arreterRepetition; /* (p8-5c) plus rien par-dessus l'entête : il change de classe */ S._repTick = setInterval(() => { const s2 = Math.round((Date.now() - S.repT0) / 1000); const c = $('rep-chrono'); if (c) c.textContent = String(Math.floor(s2 / 60)).padStart(2, '0') + ':' + String(s2 % 60).padStart(2, '0'); const o = $('rep-ou'); if (o) { const e = ecran(); const d = etatDiapo(); o.textContent = '· diapo ' + (rangDe(S.di, e.heure) || '?') + ', dévoilée ' + d.nDev + ' / ' + elements(e).length; } }, 500); dr_tout(); }

function arreterRepetition(){ if (!S.repetition) return; clearInterval(S._repTick); const snap = S.repSnap; const di = S.di; const murPart = S.murPart; /* (p8-5e) la hauteur des notes n'est pas du jeu : elle reste */ Object.keys(S).forEach(k => { if (!k.startsWith('_')) delete S[k]; }); Object.assign(S, snap.S); Object.keys(vuMax).forEach(k => delete vuMax[k]); Object.assign(vuMax, snap.vuMax); Object.keys(parDiapo).forEach(k => delete parDiapo[k]); Object.assign(parDiapo, snap.parDiapo); J.length = snap.Jlen; if (snap.ecrans) { const E0 = dr_seances()/* E1 : lisait DATA.seances */[S.si].ecrans; E0.splice(0, E0.length, ...snap.ecrans); } /* (p8-4) ce qui a été écrit en répétition est oublié */ S.repetition = false; delete S.repSnap; S.di = di; if (murPart != null) S.murPart = murPart; document.querySelector('.haut').classList.remove('p8-rep'); /* (p8-5c) l'entête redevient normal */ if (fenetreMur && !fenetreMur.closed) { try { fenetreMur.postMessage({ et: null, sortie: true }, '*'); } catch (e) {} } voir('atelier'); }

function dr_palier(...a){ if (S.repetition) return; /* (p6) pas de T-5 en répétition */ return palier0(...a); }

function rendreDroiteAtelier(){ const da = $('droite-atelier'); if (!da || !S.atelier) return; const hd = droiteAtelier(); const ecrit8 = document.activeElement && document.activeElement.id === 'p8-src' && da.contains(document.activeElement); /* (p8-3) on n'efface pas le champ où Paul écrit */ if (da.innerHTML !== hd && !ecrit8) { da.innerHTML = hd; p8BrancherPanneau(da); const ax = da.querySelector('#at-aide .x'); if (ax) ax.onclick = () => { S.aideFermee = true; dr_tout(); }; const ar = da.querySelector('#at-regler'); if (ar) ar.onclick = ouvrirARegler; brancherDeclare(da); } }

/* ── (p8-2) la préhension de l'ancien déroulé (tirSch, jalSch, PRIS, le mousedown sur g.n / g.jal), reprise dans l'atelier seulement (T6) : pendant qu'on tire, seul le dessin du schéma est mis à jour ; au pilotage et au tableau, rien ne se déplace ── */
let P8_PRIS = {}, p8Tir = null, p8Jal = null;

function p8MarquePris(){ document.querySelectorAll('#mur .p8-sch g.p8-n').forEach(g => g.classList.toggle('p8-pris', !!P8_PRIS[g.dataset.k])); }

function p8Redessiner(bi){ const z = document.querySelector('#mur .p8-dessin[data-p8="' + bi + '"]'); const b = ecran().blocs[bi]; if (!z || !b) return; poserHtml(z, p8Dessin(b, z.clientWidth, z.clientHeight, $('mur').clientHeight || 616, TAILLES[S.taille].pt, Infinity, null, true, z.dataset.titre)); p8MarquePris(); }

dr_ecouteDoc('mousedown', ev => { if (!S.atelier || S.repetition || ev.button !== 0) return; const z = ev.target.closest && ev.target.closest('#mur .p8-dessin'); if (!z) return; const bi = +z.dataset.p8; const b = ecran().blocs[bi]; if (!b || b.t !== 'schema') return; const sv = z.querySelector('svg.p8-svg');
  /* — un point de frise : sa date suit — */ const jl = ev.target.closest('g.p8-jal'); if (jl && sv) { p8Jal = { bi, i: +jl.dataset.i, min: +jl.dataset.min, max: +jl.dataset.max, W: +jl.dataset.w }; ev.preventDefault(); ev.stopPropagation(); return; }
  /* — une bulle — */ const g = ev.target.closest('g.p8-n'); if (g && sv) { const k = g.dataset.k; if (ev.ctrlKey || ev.metaKey) { if (P8_PRIS[k]) delete P8_PRIS[k]; else P8_PRIS[k] = 1; p8MarquePris(); ev.preventDefault(); ev.stopPropagation(); return; } if (!P8_PRIS[k]) { P8_PRIS = {}; P8_PRIS[k] = 1; p8MarquePris(); } const vb = sv.viewBox.baseVal, r2 = sv.getBoundingClientRect(), dep = {}; Object.keys(P8_PRIS).forEach(kk => { const gg = z.querySelector('g.p8-n[data-k="' + kk + '"]'); if (!gg) return; const rc = gg.querySelector('rect'); dep[kk] = { x: +rc.getAttribute('x') + +rc.getAttribute('width') / 2, y: +rc.getAttribute('y') + +rc.getAttribute('height') / 2 }; }); p8Tir = { bi, dep, sx: ev.clientX, sy: ev.clientY, kx: vb.width / r2.width, ky: vb.height / r2.height, W: +sv.dataset.w, H: +sv.dataset.h, bouge: false }; ev.preventDefault(); ev.stopPropagation(); return; }
  if (!ev.ctrlKey && !ev.metaKey) { P8_PRIS = {}; p8MarquePris(); } }, true);

dr_ecouteDoc('mousemove', ev => { if (!S.atelier) { p8Tir = null; p8Jal = null; return; }
  if (p8Jal) { const z = document.querySelector('#mur .p8-dessin[data-p8="' + p8Jal.bi + '"]'); const sv = z && z.querySelector('svg.p8-svg'); if (!sv) return; const vb = sv.viewBox.baseVal, r = sv.getBoundingClientRect(); const u = vb.x + (ev.clientX - r.left) * (vb.width / r.width), W = p8Jal.W; const frac = Math.max(0, Math.min(1, (u - W * 0.07) / (W * 0.86))); let d = Math.round(p8Jal.min + frac * (p8Jal.max - p8Jal.min)); d = Math.max(p8Jal.min, Math.min(p8Jal.max, d)); const b = ecran().blocs[p8Jal.bi]; if (!b) return; const L = String(b.src || '').split('\n'); const autres = L.map((s2, n) => n === p8Jal.i ? null : parseInt(s2.replace(/\D/g, ''), 10)).filter(x => x !== null && !isNaN(x)); const pasMin = Math.max(1, Math.round((p8Jal.max - p8Jal.min) / 28)); autres.forEach(a => { if (Math.abs(d - a) < pasMin) d = (d > a ? a + pasMin : a - pasMin); }); const sep = L[p8Jal.i].indexOf(':') >= 0 ? ':' : '='; const p = L[p8Jal.i].split(sep); L[p8Jal.i] = d + ' ' + sep + (p.slice(1).join(sep) || ''); b.src = L.join('\n'); p8Jal.bouge = true; p8Redessiner(p8Jal.bi); return; }
  if (p8Tir) { const z = document.querySelector('#mur .p8-dessin[data-p8="' + p8Tir.bi + '"]'); const sv = z && z.querySelector('svg.p8-svg'); if (sv) { const vb = sv.viewBox.baseVal, r2 = sv.getBoundingClientRect(); p8Tir.kx = vb.width / r2.width; p8Tir.ky = vb.height / r2.height; } const dx = (ev.clientX - p8Tir.sx) * p8Tir.kx, dy = (ev.clientY - p8Tir.sy) * p8Tir.ky; if (!p8Tir.bouge && Math.hypot(dx, dy) < 2) return; const b = ecran().blocs[p8Tir.bi]; if (!b) return; b.pos = Object.assign({}, b.pos || {}); /* le repère 1000 × 560, étiré sur la place « plein » (T6) */ Object.keys(p8Tir.dep).forEach(k => { b.pos[k] = { x: Math.round((p8Tir.dep[k].x + dx) / (p8Tir.W / 1000) * 10) / 10, y: Math.round((p8Tir.dep[k].y + dy) / (p8Tir.H / 560) * 10) / 10 }; }); p8Tir.bouge = true; p8Redessiner(p8Tir.bi); } });

dr_ecouteDoc('mouseup', () => { const t = p8Tir || p8Jal; if (t && t.bouge) { marquerModif(p8Tir ? { di: S.di, bi: t.bi, place: Object.keys(p8Tir.dep) } : { di: S.di, bi: t.bi, date: true }); dr_tout(); setTimeout(p8MarquePris, 0); } p8Tir = null; p8Jal = null; });

/* ── (p8-3) UN SCHÉMA PAR DIAPO : les gestes et leurs gardes (mandat p8, décisions 1, 5, 6 bis, 6 ter, 7) ── */
const P8_FORMES = [['carte', 'Carte mentale', 'le titre au centre, une couleur par famille, une bulle par notion'], ['frise', 'Frise', 'une date par repère, sur une ligne du temps'], ['arbre', 'Arbre', 'un nœud par ligne, la profondeur par l\'indentation'], ['cycle', 'Cycle', 'des étapes sur un cercle, reliées par des flèches'], ['tableau', 'Tableau', 'des colonnes et des rangées']];

/* la règle d'écriture de chaque forme, sous le champ — celle du panneau de l'existant (la frise lit aussi « = », comme les feuilles) */
const P8_REGLES = { carte: 'Une famille par ligne, membres après « : », séparés par des virgules.', frise: 'Une date par ligne, événement après « : » (ou « = », comme dans les feuilles). Tire un point pour changer sa date.', arbre: 'Un niveau par indentation (deux espaces).', cycle: 'Une étape par ligne, dans l\'ordre.', tableau: 'Première ligne = colonnes. Cellules séparées par « | ».' };

const P8_UNE = 'une diapo à schéma porte son titre, le schéma et au plus une consigne d\'une ligne';

function p8DiapoASchema(e){ return !!e && (e.blocs || []).some(b => b.t === 'schema'); }

function p8LignesConsigne(b){ return [b.txt].concat(b.el || []).filter(x => String(x || '').trim()).length; }

function p8ConsigneUneLigne(b){ return b.t === 'consigne' && p8LignesConsigne(b) <= 1; }

/* la diapo n'a que son titre, et au plus une consigne d'une ligne : un schéma s'y pose */
function p8DiapoLibre(e){ const bs = e.blocs || []; return bs.length === 0 || (bs.length === 1 && p8ConsigneUneLigne(bs[0])); }

/* un schéma noyé dans du texte, ou deux schémas : la trame d'avant la règle */
function p8AvecTexte(e){ const bs = e.blocs || []; const sch = bs.filter(b => b.t === 'schema'); if (!sch.length) return false; const autres = bs.filter(b => b.t !== 'schema'); return sch.length > 1 || autres.length > 1 || (autres.length === 1 && !p8ConsigneUneLigne(autres[0])); }

/* une diapo nouvelle juste après i : même heure, même activité, mêmes notions, le titre suivi de « (suite) », la durée partagée (le contenu de la diapo d'origine ne change pas) */
/* « même titre suivi de (suite) » : un titre qui finit déjà par « (suite) » le garde tel quel (pas de « (suite) (suite) ») */
function p8Suite(t){ return /\(suite\)\s*$/.test(t) ? t : t + ' (suite)'; }

function p8DiapoApres(i, blocs){ const E = seance().ecrans; const e = E[i]; const n = { eid: nouvelEid(), act: p8Suite(e.act), heure: e.heure, dur: Math.round((e.dur || 0) / 2), actId: e.actId, comp: (e.comp || []).slice(), remob: (e.remob || []).slice(), blocs }; e.dur = (e.dur || 0) - n.dur; E.splice(i + 1, 0, n); return n; }

/* « Schéma… » : sur une diapo qui a déjà du contenu, le schéma part dans une diapo nouvelle, juste après (décision 1) */
function p8PoserSchema(b){ const E = seance().ecrans; const i = S.di; const e = E[i]; if (p8DiapoASchema(e)) { toast('Une diapo n\'a qu\'un schéma.'); return; } if (p8DiapoLibre(e)) { ajouterBloc(b, false); return; } if (e.role === 'bilan') { toast('Rien ne s\'insère après le bilan : pose le schéma sur une diapo avant lui.'); return; } b.bid = nouveauBid(); const n = p8DiapoApres(i, [b]); fermerChoix(); apresTrame({ di: i, schemaApres: n.eid }); S.di = i + 1; S.page = null; toast('Schéma posé dans une diapo nouvelle, juste après : « ' + n.act + ' » — même heure, même activité, mêmes notions, la durée partagée ; la diapo d\'origine garde son contenu.'); dr_tout(); }

/* les gardes de « + bloc » : ce qu'on n'ajoute pas à une diapo à schéma, et pourquoi */
function p8GardeObjet(t, e){ if (!p8DiapoASchema(e)) return ''; if (t === 'schema') return 'Cette diapo a déjà son schéma, et une diapo n\'a qu\'un schéma : pose le nouveau dans la diapo suivante, ou insère une diapo (Ctrl + Entrée) et pose-le là'; if (t === 'consigne' && !(e.blocs || []).some(b => b.t !== 'schema')) return ''; return 'Cette diapo a son schéma : écris ce contenu dans la diapo suivante, ou insère une diapo (Ctrl + Entrée) pour lui'; }

/* coller sur une diapo à schéma : seule une consigne d'une ligne, s'il n'y en a pas déjà une (un schéma collé, lui, part dans une diapo nouvelle) */
function p8GardeColler(b, e){ if (!b || b.t === 'schema' || !p8DiapoASchema(e)) return ''; if (p8ConsigneUneLigne(b) && !p8GardeObjet('consigne', e)) return ''; return 'Cette diapo a son schéma : colle ce bloc dans la diapo suivante, ou insère une diapo (Ctrl + Entrée) pour lui'; }

function p8GardesBarre(){ const e = ecran(); const sch = p8DiapoASchema(e); const reste = sch && !p8GardeObjet('consigne', e) ? 'sur une diapo à schéma, seule une consigne d\'une ligne peut s\'ajouter' : ''; const SUITE = 'Cette diapo a son schéma : '; [['at-bloc', reste ? '' : SUITE + 'écris la suite dans la diapo suivante, ou coupe : clic droit sur le schéma → Couper la diapo ici'], ['at-etape', SUITE + 'une étape de plus va dans la diapo suivante — écris-la là, ou insère une diapo (Ctrl + Entrée)'], ['at-image', SUITE + 'pose l\'image dans la diapo suivante, ou insère une diapo (Ctrl + Entrée) pour elle'], ['at-fiche', SUITE + 'pose la fiche dans la diapo suivante, ou insère une diapo (Ctrl + Entrée) pour elle'], ['at-video', SUITE + 'pose la vidéo dans la diapo suivante, ou insère une diapo (Ctrl + Entrée) pour elle'], ['at-doc', SUITE + 'pose le document dans la diapo suivante, ou insère une diapo (Ctrl + Entrée) pour lui']].forEach(([id, raison]) => { const bt = $(id); if (!bt) return; if (bt.dataset.titre == null) bt.dataset.titre = bt.title; const grise = sch && !!raison; bt.disabled = grise; bt.classList.toggle('p8-grise', grise); bt.title = grise ? raison + '.' : (id === 'at-bloc' && reste ? bt.dataset.titre + ' — ' + reste + '.' : bt.dataset.titre); }); }

/* « Couper le schéma ici » : la bulle de tête de chaque forme (famille, repère, nœud de premier niveau, étape, rangée) */
function p8TeteDe(b, g){ const L = p8Lignes(b); const f = b.forme || 'carte'; if (g.tagName === 'TR') { const rangs = Array.from(g.parentElement.children); const k = rangs.indexOf(g); return { li: k, tete: true, nom: (L[k] || '').split('|').map(x => x.trim()).filter(Boolean).join(' · '), quoi: k === 0 ? 'la rangée des en-têtes' : 'la rangée ' + (k + 1) }; } const k = g.dataset.k; const nom = (g.querySelector('text') || g).textContent.trim();
  if (f === 'carte') { for (let i = 0; i < L.length; i++) { const p = L[i].split(':'); const fam = (p[0] || '').trim(); if (p8Cle(fam) === k) return { li: i, tete: true, nom, quoi: 'la famille ' + (i + 1) + ' sur ' + L.length }; if ((p[1] || '').split(',').map(x => x.trim()).filter(Boolean).some(m => p8Cle(m) === k)) return { li: i, tete: false, nom, quoi: 'une notion de la famille « ' + fam + ' »' }; } return { li: -1, tete: false, nom, quoi: 'le centre' }; }
  for (let i = 0; i < L.length; i++) { const s = L[i]; let c; if (f === 'frise') { let p = s.split(':'); if (p.length < 2) p = s.split('='); c = p8Cle(parseInt((p[0] || '').replace(/\D/g, ''), 10) + (p[1] || '').trim()); } else c = p8Cle(s.trim()); if (c === k) { const d = (s.match(/^ */) || [''])[0].length / 2; const tete = f !== 'arbre' || d <= 1; return { li: i, tete, nom, quoi: f === 'frise' ? 'le repère ' + (i + 1) : f === 'arbre' ? (d === 0 ? 'la racine' : d <= 1 ? 'un nœud de premier niveau' : 'un nœud plus bas') : f === 'cycle' ? 'l\'étape ' + (i + 1) : 'la ligne ' + (i + 1) }; } } return { li: -1, tete: false, nom, quoi: '' }; }

function p8MenuBulle(g, ev){ const z = g.closest('.p8-dessin'); const bi = +z.dataset.p8; const e = ecran(); const b = e.blocs[bi]; if (!b || b.t !== 'schema') return; const t = p8TeteDe(b, g); const premiere = t.tete && t.li === 0;
  const items = [{ a: 'titre', l: `« ${t.nom} » · ${t.quoi}`, off: true }, '-', { a: 'p8-couper', l: 'Couper le schéma ici', off: !t.tete || premiere || t.li < 0, t: !t.tete || t.li < 0 ? 'Cette bulle n\'est pas une bulle de tête : le schéma se coupe sur une famille, un repère, un nœud de premier niveau, une étape ou une rangée — fais le clic droit sur l\'une d\'elles' : premiere ? 'rien avant : rien à couper — fais le clic droit sur une famille plus loin : elle et la suite partiront dans un second schéma' : 'Cette bulle et tout ce qui la suit dans la source partent dans un second schéma, même titre suivi de « (suite) », sur une diapo nouvelle juste après — même heure, même activité, mêmes notions, la durée partagée ; les places données à la main les suivent' }];
  menuA($('menu'), ev.clientX, ev.clientY, items); $('menu').onclick = ev2 => { const bt = ev2.target.closest('[data-a]'); if (!bt || bt.disabled) return; $('menu').classList.remove('on'); journal('atelier-menu', { di: S.di, bi, action: bt.dataset.a, li: t.li }); if (bt.dataset.a === 'p8-couper') p8CouperSchema(S.di, bi, t.li); }; }

function p8CouperSchema(i, bi, li){ const E = seance().ecrans; const e = E[i]; const b = e.blocs[bi]; const L = p8Lignes(b); if (li <= 0 || li >= L.length) return; if (e.role === 'bilan') { toast('Rien ne s\'insère après le bilan.'); return; } const f = b.forme || 'carte';
  const cles = l => { if (f === 'carte') { const p = l.split(':'); return [p8Cle((p[0] || '').trim())].concat((p[1] || '').split(',').map(x => x.trim()).filter(Boolean).map(p8Cle)); } if (f === 'frise') { let p = l.split(':'); if (p.length < 2) p = l.split('='); return [p8Cle(parseInt((p[0] || '').replace(/\D/g, ''), 10) + (p[1] || '').trim())]; } return [p8Cle(l.trim())]; };
  const partent = new Set(L.slice(li).flatMap(cles)); const pos1 = {}, pos2 = {}; Object.keys(b.pos || {}).forEach(k => { (partent.has(k) ? pos2 : pos1)[k] = b.pos[k]; });
  const b2 = JSON.parse(JSON.stringify(b)); b2.bid = nouveauBid(); b2.txt = p8Suite(b.txt || ''); b2.src = L.slice(li).join('\n'); b2.el = L.slice(li).map(x => x.trim()); b2.pos = pos2; b.src = L.slice(0, li).join('\n'); b.el = L.slice(0, li).map(x => x.trim()); b.pos = pos1;
  const vue = !!vuMax[K(i)] || J.some(x => x.type === 'diapo' && x.eid === e.eid); const n = p8DiapoApres(i, [b2]); apresTrame({ di: i, coupeSchema: li, suite: n.eid, vue }); toast('Schéma coupé : « ' + b2.txt + ' » sur une diapo nouvelle, juste après — même heure, même activité, mêmes notions, la durée partagée ; les places données à la main suivent leurs bulles.' + (vue ? ' Une classe a déjà vu cette diapo : elle garde sa copie, seule la trame change.' : '')); dr_tout(); }

/* le panneau du schéma, repris de l'existant (décision 6 bis) : la forme, « Un à un / Tout ensemble », le contenu et sa règle d'écriture, « ⌖ Réordonner » */
function p8Panneau(e){ const bi = (e.blocs || []).findIndex(b => b.t === 'schema'); if (bi < 0) return ''; const b = e.blocs[bi]; const f = b.forme || 'carte'; const un = b.devoilerTout === false;
  return `<div class="at-d p8-panneau" id="p8-panneau" data-bi="${bi}"><h5>SCHÉMA — « ${dr_esc(b.txt || '')} »</h5><div class="p8-rgl">${P8_FORMES.map(x => `<button class="${f === x[0] ? 'on' : ''}" data-p8forme="${x[0]}" title="${f === x[0] ? 'La forme du schéma : ' + x[1].toLowerCase() + ' (' + x[2] + ')' : 'Dessine ce schéma en ' + x[1].toLowerCase() + ' : ' + x[2] + ' — les places données à la main seront perdues'}">${x[1]}</button>`).join('')}</div><div class="p8-rgl"><button class="${un ? 'on' : ''}" data-p8dev="un" title="Un à un : chaque ▶ fait paraître une bulle (la famille, puis chacune de ses notions), dans l'ordre de la source">Un à un</button><button class="${un ? '' : 'on'}" data-p8dev="tout" title="Tout ensemble : le schéma paraît d'un coup, entier ; ▶ passe à la suite">Tout ensemble</button></div><label for="p8-src">Contenu</label><textarea id="p8-src" rows="5" spellcheck="false" title="La source du schéma, une ligne par élément : ce que tu écris ici est dessiné aussitôt">${dr_esc(b.src || '')}</textarea><div class="p8-regle">${dr_esc(P8_REGLES[f] || '')}</div><button class="p8-reord" id="p8-reordonner" title="Efface les places données à la main : chaque bulle reprend sa place calculée — les places données à la main seront perdues">⌖ Réordonner</button></div>`; }

function p8BrancherPanneau(da){ const z = da.querySelector('#p8-panneau'); if (!z) return; const b = () => ecran().blocs[+z.dataset.bi];
  z.querySelectorAll('[data-p8forme]').forEach(bt => bt.onclick = () => { const s = b(); if (!s || s.forme === bt.dataset.p8forme) return; s.forme = bt.dataset.p8forme; s.pos = {}; marquerModif({ di: S.di, forme: s.forme }); dr_tout(); });
  z.querySelectorAll('[data-p8dev]').forEach(bt => bt.onclick = () => { const s = b(); if (!s) return; s.devoilerTout = bt.dataset.p8dev === 'tout'; marquerModif({ di: S.di, devoilerTout: s.devoilerTout }); dr_tout(); });
  const ta = z.querySelector('#p8-src'); ta.oninput = () => { const s = b(); if (!s) return; s.src = ta.value.replace(/\r/g, ''); s.el = p8Lignes(s).map(x => x.trim()); marquerModif({ di: S.di, src: s.src.length }); dr_tout(); }; ta.onkeydown = ev => ev.stopPropagation(); ta.onblur = () => setTimeout(dr_tout, 0);
  z.querySelector('#p8-reordonner').onclick = () => { const s = b(); if (!s) return; s.pos = {}; marquerModif({ di: S.di, reordonne: true }); toast('Réordonné : chaque bulle a repris sa place calculée.'); dr_tout(); }; }

/* ═══ (p8-4) ÉCRIRE DIRECTEMENT DANS LA DIAPO — complément p8-4 (version 2) : dans l'atelier, et en répétition (l'instantané de la séance l'oublie à l'arrêt).
   Pendant une heure lancée, le texte des blocs reste fermé (p8-5). Chaque nom est préfixé p8 et cherché dans le gabarit avant d'être écrit (n°12 · 40). ═══ */
function p8EcritureOuverte(){ return !!(S.atelier || S.repetition); }

/* sous le dernier bloc : pas sur la diapo de fin d'heure (le cahier de textes), pas sur une diapo à schéma (son titre, le schéma, au plus une consigne d'une ligne) */
function p8PeutEcrireSous(e){ return !!e && e.role !== 'fin' && !p8DiapoASchema(e); }

function p8ZoneEcrire(){ return '<div class="p8-ecrire" contenteditable="plaintext-only" spellcheck="false" data-p8ecrire="1" title="Clique ici et écris : un bloc de texte se crée sous le dernier, avec son identité dès la première lettre. Entrée ouvre une nouvelle ligne : un nouvel élément, qui se dévoilera à son tour."></div>'; }

/* décision 2 et 5 : la première lettre tapée sous le dernier bloc crée un bloc « texte » (son identité tout de suite), dont chaque ligne est un élément */
function p8EcrireSous(z){ const txt = z.textContent; if (!txt || !p8EcritureOuverte()) return; const e = ecran(); if (!p8PeutEcrireSous(e)) { z.textContent = ''; return; } const b = { t: 'texte', bid: nouveauBid(), txt: '', el: [txt] }; e.blocs.push(b); const bi = e.blocs.length - 1; z.textContent = ''; z.blur(); /* le redessin ne touche jamais le nœud qui a le focus : la zone le rend, le bloc neuf prend sa place */ marquerModif({ di: S.di, bloc: 'ajout', type: 'texte', bi, tape: true }); dr_tout(); { const nv0 = $('mur').querySelector('[data-p="' + bi + '.0"]'); if (nv0) focaliser(nv0); } /* E1 : tout de suite (le redessin du site est plus long que celui de la maquette) */ setTimeout(() => { const nv = $('mur').querySelector('[data-p="' + bi + '.0"]'); if (nv && document.activeElement !== nv) focaliser(nv); }, 0); }

/* décision 4 : « Changer de type » — le bloc prend en entier le contrat de son nouveau type, comme créé par le menu ; une ligne reste un élément */
const P8_TYPES = [['texte', 'Texte', 'Chaque ligne devient une ligne du texte : un élément, qui se dévoile à son tour'], ['consigne', 'Consigne', 'Chaque ligne devient une étape de la consigne, qui se dévoile à son tour'], ['question', 'Question', 'Chaque ligne devient une question, avec sa réponse attendue à écrire dessous ; chaque question se dévoile à son tour'], ['schema', 'Schéma', 'Chaque ligne devient une famille de la carte (« famille : notions ») ; le schéma se dévoile bulle par bulle ; s\'il y a autre chose sur la diapo, il part dans une diapo nouvelle, juste après']];

function p8LignesDe(b){ if (b.t === 'schema') return p8Lignes(b); return [b.txt].concat(b.el || []).map(x => String(x == null ? '' : x)).filter(x => x.trim()); }

function p8GardeType(b, e){ if (!b || !P8_TYPES.some(x => x[0] === b.t)) return 'Ce bloc n\'est pas fait de lignes de texte : son type ne change pas — pour un autre objet, passe par « + bloc »'; if (p8DiapoASchema(e) && b.t !== 'schema') return 'Cette diapo a son schéma : écris la suite dans la diapo suivante, ou coupe : clic droit sur le schéma → Couper la diapo ici'; return ''; }

function p8GardeVers(b, t, e){ const g = p8GardeType(b, e); if (g) return g; if (b.t === t) return 'C\'est déjà son type'; if (t === 'schema') { const autres = e.blocs.filter(x => x !== b); const seul = !autres.length || (autres.length === 1 && p8ConsigneUneLigne(autres[0])); if (!seul && e.role === 'bilan') return 'Rien ne s\'insère après le bilan : écris ce schéma sur une diapo avant lui'; } return ''; }

function p8MenuType(bi, x, y){ const e = ecran(); const b = e.blocs[bi]; if (!b) return; const items = [{ a: 'titre', l: `Changer de type — bloc ${bi + 1} · ${(b.t || '').toUpperCase()}`, off: true }, '-'].concat(P8_TYPES.map(([t, l, d]) => { const g = p8GardeVers(b, t, e); return { a: 'p8t-' + t, l, off: !!g, t: g || d }; }));
  setTimeout(() => menuA($('menu'), x, y, items), 0); /* après le clic qui l'ouvre : ce clic ferme les menus en remontant */ $('menu').onclick = ev2 => { const bt = ev2.target.closest('[data-a]'); if (!bt || bt.disabled || !/^p8t-/.test(bt.dataset.a)) return; $('menu').classList.remove('on'); p8ChangerType(bi, bt.dataset.a.slice(4)); }; }

function p8ChangerType(bi, t){ const i = S.di; const e = ecran(); const b = e.blocs[bi]; if (!b || p8GardeVers(b, t, e)) return; const L = p8LignesDe(b); const avant = b.t; let nv;
  if (t === 'question') nv = (L.length ? L : ['']).map((x, k) => ({ t: 'question', bid: k ? nouveauBid() : b.bid, txt: x, el: [''] }));   /* comme par le menu : la question, puis sa réponse attendue (ici à écrire) */
  else if (t === 'schema') nv = [{ t: 'schema', bid: b.bid, txt: e.act, forme: 'carte', src: L.join('\n'), el: L.slice(), devoilerTout: false }];   /* créé par un geste : « Un à un » (décision 6 ter) */
  else nv = [{ t, bid: b.bid, txt: '', el: L.length ? L : [''] }];
  if (b.taille && b.taille !== 'normal' && !(t === 'schema' && b.taille === 'petit')) nv.forEach(x => { x.taille = b.taille; });
  const autres = e.blocs.filter(x => x !== b); const seul = !autres.length || (autres.length === 1 && p8ConsigneUneLigne(autres[0]));
  if (t === 'schema' && !seul) { e.blocs.splice(bi, 1); p8NotesBloc(i, bi, 'supprimer'); /* (p8-5c) */ const n = p8DiapoApres(i, nv); apresTrame({ di: i, typeSchema: n.eid }); toast('Type changé en schéma : il part dans une diapo nouvelle, juste après (« ' + n.act + ' ») — une diapo à schéma porte son titre, le schéma et au plus une consigne d\'une ligne.'); dr_tout(); return; }
  e.blocs.splice(bi, 1, ...nv); p8NotesBloc(i, bi, 'type', nv.length); /* (p8-5c) les lignes changent de nature : les notes du bloc reviennent à ⌂ */ marquerModif({ di: i, bi, type: avant + '→' + t, n: nv.length }); toast(t === 'question' && nv.length > 1 ? 'Type changé : ' + nv.length + ' questions, une par ligne — chacune avec sa réponse attendue à écrire dessous.' : 'Type changé : le bloc prend la disposition de son type ; chaque ligne reste un élément.'); dr_tout(); }

dr_ecouteDoc('input', ev => { const z = ev.target && ev.target.closest && ev.target.closest('#mur .p8-ecrire'); if (z) p8EcrireSous(z); }, true);

dr_ecouteDoc('keydown', ev => { const z = ev.target && ev.target.closest && ev.target.closest('#mur .p8-ecrire'); if (z && (ev.key === 'Enter' || ev.key === 'Tab')) { ev.preventDefault(); ev.stopPropagation(); } }, true);

/* ═══ (p8-5) ÉCRIRE EN CLASSE, DANS LA COPIE DE LA CLASSE — complément p8-5 ; cadrage 1 §8.4 : ce que Paul modifie en séance vit dans la copie de la classe ;
   à la fin de l'heure, le site compare la copie et la trame par identité et propose le versement, diapo par diapo (oui / non).
   La donnée, comme le vrai site la tiendra : S.copie[heure][eid de la diapo][bid du bloc] = { t: texte de tête, el: { rang: texte } } — une copie par classe
   (la maquette n'a qu'une classe) et par heure, ancrée par identité de diapo et de bloc ; pas de second jeu de diapos. ═══ */
function p8EnClasse(){ return !!(S.lancee && !S.repetition && !S.atelier && !S.close); }

function p8CopieDiapo(h, eid){ S.copie = S.copie || {}; const H = S.copie[h] = S.copie[h] || {}; return H[eid] = H[eid] || {}; }

/* la frappe en classe va dans la copie, jamais dans la trame ; le pilote et le tableau la montrent (le texte qui a le focus n'est jamais touché par le redessin) */
function p8EcrireCopie(el){ const b = blocDe(el); if (!b) return; const e = ecran(); const bloc = e.blocs[b.bi]; if (!bloc || !bloc.bid) return; const c = p8CopieDiapo(S.heure, e.eid); const cb = c[bloc.bid] = c[bloc.bid] || {}; const txt = el.textContent; if (b.ei === 't') cb.t = txt; else (cb.el = cb.el || {})[b.ei] = txt; journal('copie-classe', { di: S.di, eid: e.eid, bid: bloc.bid, ei: b.ei, n: txt.length }); dr_tout(); }

/* ce que la copie change dans une diapo, par identité de bloc : seulement ce qui diffère de la trame */
function p8DiffCopie(h, e){ const c = ((S.copie || {})[h] || {})[e.eid] || {}; const out = []; Object.keys(c).forEach(bid => { const b = (e.blocs || []).find(x => x.bid === bid); if (!b) return; const cb = c[bid]; if (cb.t != null && cb.t !== (b.txt || '')) out.push({ bid, ei: 't', avant: b.txt || '', apres: cb.t }); Object.keys(cb.el || {}).forEach(ei => { const av = (b.el || [])[+ei]; if (av != null && cb.el[ei] !== av) out.push({ bid, ei: +ei, avant: av, apres: cb.el[ei] }); }); }); return out; }

/* au rendu (pilote et tableau) : la copie de la classe, posée par identité sur les textes de la diapo */
function p8TextesCopie(e, textes){ const c = ((S.copie || {})[S.heure] || {})[e.eid]; if (!c) return textes; const t = Object.assign({}, textes || {}); (e.blocs || []).forEach((b, bi) => { const cb = c[b.bid]; if (!cb) return; if (cb.t != null) t[bi + '.t'] = cb.t; Object.keys(cb.el || {}).forEach(ei => { t[bi + '.' + ei] = cb.el[ei]; }); }); return t; }

/* « oui » : la trame prend ce que la classe a vu, bloc par bloc, par identité */
function p8Verser(h, eid){ const e = seance().ecrans.find(x => x.eid === eid); if (!e) return 0; const d = p8DiffCopie(h, e); d.forEach(x => { const b = e.blocs.find(y => y.bid === x.bid); if (x.ei === 't') b.txt = x.apres; else b.el[x.ei] = x.apres; }); journal('versement-trame', { eid, h, n: d.length }); return d.length; }

/* « Fin de l'heure » : la liste des diapos modifiées, chacune avec « verser dans la trame » oui / non, en clair ; sans réponse, la trame ne change pas */
function p8CopieDiffere(){ return seance().ecrans.some(e => p8DiffCopie(S.heure, e).length > 0); }

function p8ListeVersement(){ const h = S.heure; const E = seance().ecrans; const L = E.map((e, i) => ({ e, i, d: p8DiffCopie(h, e) })).filter(x => x.d.length); const dec = (S.versements || {})[h] || {};
  if (!L.length) return '<span style="color:var(--sourd)">aucune</span>';
  return '<div class="p8-verse-liste">' + L.map(x => `<div class="p8-verse" data-p8eid="${dr_esc(x.e.eid)}"><div class="p8-verse-t">Diapo ${rangDe(x.i, x.e.heure) || x.i + 1} · « ${dr_esc(x.e.act)} » — ${x.d.length} texte${x.d.length > 1 ? 's' : ''} écrit${x.d.length > 1 ? 's' : ''} en classe :</div>${x.d.map(y => `<div class="p8-verse-d">la classe a vu « <b>${dr_esc(y.apres)}</b> » — la trame dit « ${dr_esc(y.avant)} »</div>`).join('')}<div class="p8-verse-q">${(dec[x.e.eid] || {}).sig === JSON.stringify(x.d) ? '<span class="p8-verse-dit">Tu as dit non : la trame ne change pas.</span>' : 'Verser dans la trame ? <button class="btn" data-p8verse="oui" title="La trame prend ce que la classe a vu : la prochaine classe le verra">Oui, verser</button> <button class="btn" data-p8verse="non" title="La trame ne change pas : ce que cette classe a vu reste dans sa copie, et dans le récit">Non, garder la trame</button> <span class="p8-verse-dit"></span>'}</div></div>`).join('') + '<div class="p8-verse-sans">Sans réponse, la trame ne change pas.</div></div>'; }

dr_ecouteDoc('click', ev => { const bt = ev.target.closest && ev.target.closest('[data-p8verse]'); if (!bt) return; const z = bt.closest('.p8-verse'); if (!z || z.dataset.p8fait) return; const eid = z.dataset.p8eid, oui = bt.dataset.p8verse === 'oui'; const h = S.heure; const e0 = seance().ecrans.find(x => x.eid === eid); S.versements = S.versements || {}; (S.versements[h] = S.versements[h] || {})[eid] = { r: oui ? 'oui' : 'non', sig: e0 ? JSON.stringify(p8DiffCopie(h, e0)) : '' }; /* un « non » vaut pour ce qui a été montré : une correction de plus repose la question */
  if (oui) { const n = p8Verser(h, eid); z.querySelector('.p8-verse-dit').textContent = 'Versé dans la trame (' + n + ' texte' + (n > 1 ? 's' : '') + ').'; } else { journal('versement-refuse', { eid, h }); z.querySelector('.p8-verse-dit').textContent = 'La trame ne change pas.'; }
  z.dataset.p8fait = oui ? 'oui' : 'non'; z.querySelectorAll('[data-p8verse]').forEach(b => { b.disabled = true; }); });

/* ═══ (p8-5c) LES NOTES DE PRÉSENTATEUR, LA MISE EN FORME — complément p8-5c (dettes n°13 · 10 et 11). La répétition propre (n°13 · 9) est dans le gabarit (classe de .haut).
   Chaque nom est préfixé p8 et cherché dans le gabarit avant d'être écrit (n°12 · 40). ═══ */
/* les couleurs : la donnée garde le NOM ; le rendu choisit la teinte, une par fond (notes et boutons sombres ici ; tableau crème dans surligne, qui passe au tableau) */
const P8_SURL = { jaune: '#ffe94a', vert: '#b6f0c2', rose: '#ffc9d6', bleu: '#bcd9ff' };

const P8_TXT_NOTES = { rouge: '#ff7b6b', vert: '#7ddc9a', bleu: '#8ab8ff', or: '#e3b94e' };

/* ── B. les notes : DATA.notes[clé de la diapo] = [{ p, html }] — p = le data-p de l'élément (null = à l'arrivée, ⌂) ; une note d'avant (une chaîne) se lit comme un paragraphe ⌂ ── */
/* les notes d'avant sont rangées « si|rang de la diapo » ('0|0', '0|6') alors que toute clé d'état par diapo est si|eid depuis a0 : elles ne s'affichaient jamais. Au premier rendu, avant tout geste, elles passent à si|eid. */
const P8_MIGRE = { fait: false };

/* l'identité du paragraphe où l'on écrit, prise quand il reçoit le focus : un redessin (l'animation, un dévoilement) peut changer de diapo pendant la frappe, et morph réécrit les attributs du nœud actif */
const P8_IDENT = new WeakMap();

function p8MigrerNotes(){ if (P8_MIGRE.fait) return; P8_MIGRE.fait = true; Object.keys(dr_notes()/* E1 : lisait DATA.notes */ || {}).forEach(k => { const m = /^(\d+)\|(\d+)$/.exec(k); if (!m) return; const se = dr_seances()/* E1 : lisait DATA.seances */[+m[1]]; const e = se && se.ecrans[+m[2]]; if (!e || e.eid == null) return; const k2 = m[1] + '|' + e.eid; if (dr_notes()/* E1 : lisait DATA.notes */[k2] == null) dr_notes()/* E1 : lisait DATA.notes */[k2] = dr_notes()/* E1 : lisait DATA.notes */[k]; delete dr_notes()/* E1 : lisait DATA.notes */[k]; }); }

function p8NotesDe(key){ const v = dr_notes()/* E1 : lisait DATA.notes */[key]; if (v == null || v === '') return []; if (typeof v === 'string') return [{ p: null, html: dr_esc(v) }]; return v; }

/* les ancres possibles : chaque élément de la diapo qui porte un texte (data-p), dans l'ordre de dévoilement, son rang = k + 1 */
function p8Ancres(e){ const out = []; elements(e).forEach((x, k) => { if (x.t === 'schema' || x.t === 'cahier') return; out.push({ p: x.q ? x.b + '.t' : x.b + '.' + x.e, k: k + 1, txt: String(x.txt == null ? '' : x.txt) }); }); return out; }

function p8RangDe(e, p){ if (p == null) return 0; const a = p8Ancres(e).find(x => x.p === p); return a ? a.k : 0; }

function p8TrierNotes(e, L){ return L.map((n, i) => ({ n, i, r: p8RangDe(e, n.p) })).sort((a, b) => a.r - b.r || a.i - b.i).map(x => x.n); }

/* l'assainissement à l'enregistrement : seuls <mark data-coul> et <span data-coul> passent (le nom de la couleur), tout le reste devient du texte */
function p8Assainir(html){ const t = document.createElement('template'); t.innerHTML = html; const out = n => Array.from(n.childNodes).map(c => { if (c.nodeType === 3) return dr_esc(c.textContent); if (c.nodeType !== 1) return ''; const coul = c.getAttribute('data-coul'); if (c.tagName === 'MARK' && P8_SURL[coul]) return '<mark data-coul="' + coul + '">' + out(c) + '</mark>'; if (c.tagName === 'SPAN' && P8_TXT_NOTES[coul]) return '<span data-coul="' + coul + '">' + out(c) + '</span>'; if (c.tagName === 'BR') return ' '; return out(c); }).join(''); return out(t.content); }

function p8ModeNotes(){ return !S.repetition && (S.atelier || p8EnClasse()) ? 'ecrire' : 'lire'; }

function p8RendreNotes(){ const z = $('notesd'); if (!z) return; p8MigrerNotes(); const e = ecran(); if (!e) return; const key = cle(); const af = document.activeElement && document.activeElement.closest ? document.activeElement.closest('#notesd .p8-mt') : null; if (af && (P8_IDENT.has(af) ? P8_IDENT.get(af).key : af.dataset.p8key) !== key) af.blur(); /* (p8-5d) le panneau suit la diapo courante, toujours : le paragraphe d'une autre diapo rend le focus avant le rendu ; ce qui était tapé est déjà enregistré */ const L = p8NotesDe(key); const ed = p8ModeNotes() === 'ecrire'; const nDev = etatDiapo().nDev || 0; const rangs = L.map(n => p8RangDe(e, n.p)); const vide = L.map(n => !ed && !String(n.html || '').replace(/<[^>]*>/g, '').trim()); /* en lecture, un paragraphe vide ne se montre pas et ne s'éclaire pas */ let vif = -1; if (!S.atelier) rangs.forEach((r, i) => { if (r <= nDev && !vide[i]) vif = i; });
  const tk = r => r ? 'Accrochée à l\'élément ' + r + ' : elle s\'éclaire quand il est dévoilé' : 'À l\'arrivée sur la diapo (⌂) : elle s\'éclaire dès la diapo ouverte';
  let h = L.map((n, i) => `<div class="p8-mn${i === vif ? ' p8-vif' : i < vif ? ' p8-fait' : ''}${vide[i] ? ' p8-mvide' : ''}" data-i="${i}">${ed ? `<button class="p8-k" data-p8k="${i}" title="${dr_esc(tk(rangs[i]))} — clic : l'accrocher à un autre élément">` : `<span class="p8-k" title="${dr_esc(tk(rangs[i]))}">`}${rangs[i] || '⌂'}${ed ? '</button>' : '</span>'}<div class="p8-mt"${ed ? ' contenteditable="true" spellcheck="false"' : ''} data-p8n="${i}" data-p8key="${dr_esc(key)}">${n.html}</div></div>`).join('');
  if (!L.length) h = ed ? `<div class="p8-mn" data-i="0"><span class="p8-k" title="Le premier paragraphe s\'accroche à l\'élément où était ton curseur dans la diapo (⌂ s\'il n\'y en a pas)">⌂</span><div class="p8-mt p8-vide" contenteditable="true" spellcheck="false" data-p8n="0" data-p8key="${dr_esc(key)}"></div></div>` : '<span class="p8-rien">—</span>';
  const dedans = z.contains(document.activeElement); poserHtml(z, h);
  const pan = z.closest('.notes'); if (pan) pan.title = S.repetition ? 'Tes notes pour cette diapo — en répétition, elles se lisent sans s\'écrire : tout ce qui est joué en répétition est oublié à l\'arrêt. La note de l\'élément dévoilé s\'éclaire.' : ed ? 'Tes notes pour cette diapo, un paragraphe par moment (la classe ne les voit jamais). Entrée ouvre un paragraphe accroché à l\'élément où était ton curseur dans la diapo (⌂ : à l\'arrivée). En classe, la note de l\'élément dévoilé s\'éclaire. Le repère en marge : un clic pour l\'accrocher ailleurs — si l\'élément disparaît, la note revient à ⌂, jamais perdue.' : 'Tes notes pour cette diapo : la note de l\'élément dévoilé s\'éclaire.';
  if (!dedans) { const v = z.querySelector('.p8-vif'); if (v) v.scrollIntoView({ block: 'nearest' }); } }

function p8NoteEnregistree(i){ if (S.atelier) marquerModif({ di: S.di, notes: i }); }

/* le texte tapé dans un paragraphe : la trame (dans l'atelier et en classe ; jamais en répétition) */
function p8NoteCle(mt){ const id = P8_IDENT.get(mt); return id ? id.key : (mt.dataset.p8key || cle()); }

function p8NoteRang(mt){ const id = P8_IDENT.get(mt); return id ? id.n : +mt.dataset.p8n; }

function p8NoteEcran(key){ return seance().ecrans.find(x => S.si + '|' + x.eid === key) || ecran(); }

function p8EcrireNote(mt){ if (p8ModeNotes() !== 'ecrire') return; const key = p8NoteCle(mt); const e = p8NoteEcran(key); let L = p8NotesDe(key).slice(); const i = p8NoteRang(mt); if (!L.length) { const d = S.dernierElementNote; L = [{ p: d && p8RangDe(e, d) ? d : null, html: '' }]; } if (!L[i]) return; L[i] = Object.assign({}, L[i], { html: p8Assainir(mt.innerHTML) }); dr_notes()/* E1 : lisait DATA.notes */[key] = L; p8NoteEnregistree(i); if (mt.classList.contains('p8-vide')) p8RendreNotes(); }

/* Entrée : un nouveau paragraphe, accroché à l'élément où était le curseur juste avant de descendre dans les notes (⌂ sinon) */
function p8NouvelleNote(mt){ const key = p8NoteCle(mt); const e = p8NoteEcran(key); const L = p8NotesDe(key).slice(); const i = p8NoteRang(mt); if (!L.length) L.push({ p: null, html: p8Assainir(mt.innerHTML) }); const d = S.dernierElementNote; const n = { p: d && p8RangDe(e, d) ? d : null, html: '' }; L.splice(i + 1, 0, n); const L2 = p8TrierNotes(e, L); dr_notes()/* E1 : lisait DATA.notes */[key] = L2; p8NoteEnregistree(i + 1); mt.blur(); /* le redessin ne touche jamais le paragraphe qui a le focus : on le rend, le neuf le prend */ p8RendreNotes(); const j = L2.indexOf(n); const nv = $('notesd').querySelector('.p8-mt[data-p8n="' + j + '"]'); if (nv) nv.focus(); /* (p8-5d) dans le même geste : la touche suivante arrive dans le paragraphe neuf */ }

function p8Reaccrocher(i, x, y){ const e = ecran(); const A = p8Ancres(e); const items = [{ a: 'titre', l: 'Accrocher ce paragraphe à…', off: true }, '-', { a: 'p8a-', l: '⌂ à l\'arrivée sur la diapo', t: 'La note s\'éclaire dès la diapo ouverte' }].concat(A.map(a => ({ a: 'p8a-' + a.p, l: a.k + ' · ' + (a.txt.length > 40 ? a.txt.slice(0, 40) + '…' : a.txt || '(élément vide)'), t: 'La note s\'éclaire quand cet élément est dévoilé (▶ ' + a.k + ')' })));
  setTimeout(() => menuA($('menu'), x, y, items), 0); $('menu').onclick = ev2 => { const bt = ev2.target.closest('[data-a]'); if (!bt || bt.disabled || !/^p8a-/.test(bt.dataset.a)) return; $('menu').classList.remove('on'); const p = bt.dataset.a.slice(4) || null; const key = cle(); const L = p8NotesDe(key).slice(); if (!L[i]) return; L[i] = Object.assign({}, L[i], { p }); dr_notes()/* E1 : lisait DATA.notes */[key] = p8TrierNotes(ecran(), L); p8NoteEnregistree(i); p8RendreNotes(); }; }

/* les ancres suivent leur élément quand la structure change (dans l'atelier ; en répétition, la séance est restaurée à l'arrêt) ; un élément supprimé rend sa note ⌂ */
function p8NotesMap(di, f){ if (S.repetition) return; const key = K(di); const L = p8NotesDe(key); if (!L.length) return; let ch = false; const L2 = L.map(n => { if (n.p == null) return n; const [b, x] = String(n.p).split('.'); const r = f(+b, x === 't' ? 't' : +x); if (r === undefined) return n; ch = true; return Object.assign({}, n, { p: r }); }); if (ch) dr_notes()/* E1 : lisait DATA.notes */[key] = p8TrierNotes(seance().ecrans[di], L2); }

function p8NotesElement(di, bi, ei, act){ p8NotesMap(di, (b, x) => { if (b !== bi || x === 't') return; if (act === 'supprimer') return x === ei ? null : x > ei ? b + '.' + (x - 1) : undefined; if (act === 'inserer') return x >= ei ? b + '.' + (x + 1) : undefined; if (act === 'monter') return x === ei ? b + '.' + (ei - 1) : x === ei - 1 ? b + '.' + ei : undefined; if (act === 'descendre') return x === ei ? b + '.' + (ei + 1) : x === ei + 1 ? b + '.' + ei : undefined; }); }

function p8NotesBloc(di, bi, act, n){ p8NotesMap(di, (b, x) => { const q = c => c + '.' + x; if (act === 'supprimer') return b === bi ? null : b > bi ? q(b - 1) : undefined; if (act === 'inserer') return b >= bi ? q(b + (n || 1)) : undefined; if (act === 'echanger') return b === bi ? q(n) : b === n ? q(bi) : undefined; if (act === 'type') return b === bi ? null : b > bi ? q(b + n - 1) : undefined; }); }

/* « Couper la diapo ici » : chaque paragraphe suit son élément ; ceux des blocs qui partent vont dans la diapo « (suite) » */
function p8NotesCouper(i, bi, eidSuite){ if (S.repetition) return; const k1 = K(i); const L = p8NotesDe(k1); const reste = [], part = []; L.forEach(n => { const b = n.p == null ? -1 : +String(n.p).split('.')[0]; if (b >= bi) part.push({ p: (b - bi) + '.' + String(n.p).split('.')[1], html: n.html }); else reste.push(n); }); if (!part.length) return; dr_notes()/* E1 : lisait DATA.notes */[k1] = reste; const k2 = S.si + '|' + eidSuite; dr_notes()/* E1 : lisait DATA.notes */[k2] = p8NotesDe(k2).concat(part); }

/* ── C. la mise en forme : la cible suit la sélection (la diapo → au tableau, l'état de l'heure, le journal ; les notes → la trame, ni journal ni tableau) ── */
function p8Dire(msg){ const d = $('dern'); if (d) d.textContent = msg; toast(msg); }

function p8Cible(){ const sel = getSelection(); if (!sel.rangeCount || sel.isCollapsed) return null; const r = sel.getRangeAt(0); const n0 = r.commonAncestorContainer; const n = n0.nodeType === 1 ? n0 : n0.parentElement; if (!n || !n.closest) return { genre: 'ailleurs' }; const mt = n.closest('#notesd .p8-mt'); if (mt) return { genre: 'notes', mt, r }; const s0 = r.startContainer.parentElement; const li = s0 && s0.closest('#mur [data-p]'); if (li) return { genre: 'mur', li, r }; return { genre: 'ailleurs' }; }

function p8CouleurTexte(couleur){ const sel = getSelection(); if (!sel.rangeCount || sel.isCollapsed) { p8Dire('sélectionne d\'abord le texte à colorer — dans la diapo ou dans tes notes'); return; } const r = sel.getRangeAt(0); const li0 = r.startContainer.parentElement; const li = li0 && li0.closest('#mur [data-p]'); if (!li) { p8Dire('sélectionne d\'abord le texte à colorer — dans la diapo ou dans tes notes'); return; } const d = etatDiapo(); const txt = r.toString(); d.coulTxt = d.coulTxt || []; if (couleur) d.coulTxt.push({ p: li.dataset.p, txt, couleur }); else d.coulTxt = d.coulTxt.filter(x => !(x.p === li.dataset.p && (txt.includes(x.txt) || x.txt.includes(txt)))); journal(couleur ? 'couleur-texte' : 'couleur-texte-retire', { si: S.si, di: S.di, p: li.dataset.p, txt, couleur }); sel.removeAllRanges(); dr_tout(); }

function p8FormerNote(mt, r, genre, coul){ const tag = genre === 'surl' ? 'MARK' : 'SPAN'; if (!coul) { Array.from(mt.querySelectorAll(tag + '[data-coul]')).filter(x => r.intersectsNode(x)).forEach(x => x.replaceWith(...x.childNodes)); } else { const w = document.createElement(tag); w.setAttribute('data-coul', coul); w.appendChild(r.extractContents()); r.insertNode(w); } getSelection().removeAllRanges(); const key = p8NoteCle(mt); const L = p8NotesDe(key).slice(); const i = p8NoteRang(mt); if (!L.length) L.push({ p: null, html: '' }); if (!L[i]) return; L[i] = Object.assign({}, L[i], { html: p8Assainir(mt.innerHTML) }); dr_notes()/* E1 : lisait DATA.notes */[key] = L; p8NoteEnregistree(i); }

function p8Former(genre, coul){ const cb = p8Cible(); if (!cb) { p8Dire('sélectionne d\'abord le texte à ' + (genre === 'surl' ? 'surligner' : 'colorer') + ' — dans la diapo ou dans tes notes'); return; } if (cb.genre === 'notes') { if (p8ModeNotes() !== 'ecrire') { p8Dire('en répétition, tes notes se lisent sans s\'écrire : tout ce qui est joué est oublié à l\'arrêt'); return; } p8FormerNote(cb.mt, cb.r, genre, coul); return; } if (cb.genre === 'mur') { if (genre === 'surl') surligner(coul); else p8CouleurTexte(coul); const f = document.activeElement; if (f && f !== document.body && cb.li.contains(f)) { f.blur(); dr_tout(); } /* l'élément qui a le focus n'est jamais redessiné : on le rend, il montre la marque */ return; } p8Dire('sélectionne d\'abord le texte à ' + (genre === 'surl' ? 'surligner' : 'colorer') + ' — dans la diapo ou dans tes notes'); }

function p8TraitCouleur(){ const s = $('bsurl-trait'), t = $('btxt-trait'); if (s) s.style.background = P8_SURL[S.p8CoulSurl || 'jaune']; if (t) t.style.background = P8_TXT_NOTES[S.p8CoulTxt || 'rouge']; }

function p8FermerPalettes(){ document.querySelectorAll('.p8-palette.on').forEach(x => x.classList.remove('on')); }

/* les branchements, une fois : la palette (comme dans Word), les notes, la mémoire du dernier élément touché dans la diapo */
(function(){ ['bsurl', 'btxt'].forEach(id => { const b = $(id); if (!b) return; b.addEventListener('mousedown', ev => ev.preventDefault()); /* la sélection et le focus restent où ils sont */ b.addEventListener('click', ev => { ev.stopPropagation(); const pal = $(id === 'bsurl' ? 'pal-surl' : 'pal-txt'); const ouvrir = !pal.classList.contains('on'); p8FermerPalettes(); if (ouvrir) pal.classList.add('on'); }); });
  document.querySelectorAll('.p8-palette .p8-p').forEach(p => { p.addEventListener('mousedown', ev => ev.preventDefault()); p.addEventListener('click', ev => { ev.stopPropagation(); const genre = p.closest('.p8-palette').id === 'pal-surl' ? 'surl' : 'txt'; const c = p.dataset.c || null; if (c) { if (genre === 'surl') S.p8CoulSurl = c; else S.p8CoulTxt = c; } p8FermerPalettes(); p8TraitCouleur(); p8Former(genre, c); }); });
  dr_ecouteDoc('click', ev => { if (!ev.target.closest || !ev.target.closest('.p8-mfw')) p8FermerPalettes(); });
  dr_ecouteDoc('keydown', ev => { if (ev.key === 'Escape' && document.querySelector('.p8-palette.on')) { p8FermerPalettes(); ev.stopPropagation(); } }, true);
  dr_ecouteDoc('focusin', ev => { const x = ev.target && ev.target.closest && ev.target.closest('#mur [data-p]'); if (x && String(x.dataset.p).split('.').length === 2) S.dernierElementNote = x.dataset.p; });
  const z = $('notesd'); if (z) { z.addEventListener('focusin', ev => { const mt = ev.target.closest && ev.target.closest('.p8-mt'); if (mt) P8_IDENT.set(mt, { key: mt.dataset.p8key || cle(), n: +mt.dataset.p8n }); });
    z.addEventListener('focusout', ev => { const mt = ev.target.closest && ev.target.closest('.p8-mt'); if (mt) { P8_IDENT.delete(mt); setTimeout(p8RendreNotes, 0); } }); /* à la sortie, le paragraphe est redessiné avec sa diapo */
    z.addEventListener('input', ev => { const mt = ev.target.closest && ev.target.closest('.p8-mt'); if (mt) p8EcrireNote(mt); });
    z.addEventListener('keydown', ev => { const mt = ev.target.closest && ev.target.closest('.p8-mt'); if (!mt) return; if (ev.key === 'Enter') { ev.preventDefault(); ev.stopPropagation(); if (p8ModeNotes() === 'ecrire') p8NouvelleNote(mt); } });
    z.addEventListener('paste', ev => { const mt = ev.target.closest && ev.target.closest('.p8-mt'); if (!mt) return; ev.preventDefault(); const t = (ev.clipboardData || window.clipboardData).getData('text/plain').replace(/\s*\n\s*/g, ' '); document.execCommand('insertText', false, t); });
    z.addEventListener('click', ev => { const k = ev.target.closest && ev.target.closest('.p8-k[data-p8k]'); if (!k || p8ModeNotes() !== 'ecrire') return; ev.stopPropagation(); const r = k.getBoundingClientRect(); p8Reaccrocher(+k.dataset.p8k, r.left, r.bottom + 4); }); }
  p8TraitCouleur(); })();

function blocDe(el){ const li = el.closest('[data-p]'); if (!li) return null; const [bi, ei] = li.dataset.p.split('.'); return { bi: +bi, ei: ei === 't' ? 't' : +ei, li }; }

function marquerModif(quoi){ dr_sauve(); /* E1 : la maquette simulait l'enregistrement ; dr_sauve écrit B/deroule (900 ms) */ S.atelierDirty = Date.now(); const sv = $('at-save'); if (sv) { sv.className = 'at-save dirty'; sv.textContent = '● modification en cours — enregistrement dans 3 s'; } journal('atelier-modif', quoi); }

function ecrireDansDiapo(el){ if (p8EnClasse()) { p8EcrireCopie(el); return; } /* (p8-5) */ const b = blocDe(el); if (!b) return; const e = ecran(); const bloc = e.blocs[b.bi]; if (!bloc) return; const txt = el.textContent; if (b.ei === 't') bloc.txt = txt; else { bloc.el = bloc.el || []; bloc.el[b.ei] = txt; } marquerModif({ di: S.di, bi: b.bi, ei: b.ei, n: txt.length }); if (S.repetition) dr_tout(); else if (S.atelier) p85fSuivreFrappe(el); /* (p8-5f) */ /* (p8-4) le tableau suit la frappe ; le texte qui a le focus n'est jamais touché par le redessin */ }

function elementsEditables(){ return Array.from(document.querySelectorAll('#mur [data-p][contenteditable]')); }

function elementsDeLaDiapo(){ return Array.from(document.querySelectorAll('#mur [data-p]')); }

function focaliser(el, fin){ if (!el) return; if (S.atelier && el.closest('.hors') && el.dataset.p) { S._p85fCible = el.dataset.p; S.pageManuelle = false; dr_tout(); el = $('mur').querySelector(`[data-p="${S._p85fCible}"]`) || el; S._p85fCible = null; } /* (p8-5f) la page de la ligne d'abord */ if (!el.getAttribute('contenteditable')) brancherAtelier(); /* le rendu du mur est différé : on branche avant de mettre le curseur */ el.focus(); if (fin !== false) { const r = document.createRange(); r.selectNodeContents(el); r.collapse(false); const sel = getSelection(); sel.removeAllRanges(); sel.addRange(r); } }

const atBranches = new WeakSet();
 /* les nœuds branchés (un clone du morph n'y est pas : il sera rebranché) */
let atObs = null;
 function observerMur(){ if (atObs) return; const mur = $('mur'); if (!mur) return; atObs = new MutationObserver(() => { if (S.atelier) { brancherAtelier(); clearTimeout(S._atDroite); S._atDroite = setTimeout(rendreDroiteAtelier, 60); /* (p6) la mesure « trop pleine » se fait sur la diapo rendue */ } }); atObs.observe(mur, { childList: true, subtree: true }); }

function brancherDocs(){ const mur = $('mur'); if (!mur || S.atelier) return; const dx = mur.querySelector('[data-docx]'); if (dx && !dx._ok) { dx._ok = true; dx.onclick = ev => { ev.stopPropagation(); const id = S.doc && S.doc.id; S.doc = null; journal('doc-ferme', { id }); dr_tout(); }; } mur.querySelectorAll('[data-docbloc]').forEach(x => { if (x._doc) return; x._doc = true; x.onclick = ev => { ev.stopPropagation(); const id = x.dataset.docbloc; const d = (dr_documents()/* E1 : lisait DATA.documents */[String(S.si)] || []).find(z => z.id === id); if (!d) return; if (!['pdf', 'image', 'html', 'docx'].includes(d.type)) { alert('Ce document (' + d.type + ') n\'est pas projetable tel quel : convertis-le en PDF.'); return; } S.doc = S.doc && S.doc.id === id ? null : { id, pos: 1 }; journal(S.doc ? 'doc-ouvert' : 'doc-ferme', { id }); dr_tout(); }; }); }

function brancherAtelier(){ const mur = $('mur'); if (!mur || !(S.atelier || S.repetition || p8EnClasse())) return; /* (p8-4) en répétition aussi ; (p8-5) en classe, dans la copie */ const e = ecran(); if (!e || e.role === 'fin') return;
  elementsDeLaDiapo().filter(x => x.dataset.p.split('.').length === 2).forEach(x => { /* (p8-4) les champs de réponse (bloc.i.n, bloc.r.n) et les cases du cahier (0.c.n) gardent leur propre écriture */ if (!x.getAttribute('contenteditable')) { x.setAttribute('contenteditable', 'plaintext-only'); x.setAttribute('spellcheck', 'false'); x.title = p8EnClasse() ? 'Écris ici : la classe voit ta correction ; elle reste dans la copie de la classe — « Fin de l\'heure » te proposera de la verser dans la trame (Entrée : le texte suivant)' : S.repetition ? 'Écris ici : le tableau suit la frappe ; en répétition, tout ce que tu écris est oublié à l\'arrêt (Entrée : un nouvel élément)' : 'Écris ici : c\'est enregistré tout seul quelques secondes après (Tab : l\'élément suivant · Entrée : un nouvel élément · Échap : annule une ligne vide)'; } /* le morph réutilise les nœuds et retire les attributs absents du nouveau rendu : on les repose à chaque passage ; les écouteurs, eux, une seule fois */ if (atBranches.has(x)) return; atBranches.add(x);
    x.addEventListener('focus', () => { mur.querySelectorAll('.bloc-edit').forEach(z => z.classList.remove('bloc-edit')); const conteneur = x.closest('ul, ol, .bloc, p') || x.parentElement; if (!S.atelier) return; /* (p8-4) en répétition, (p8-5) en classe : on écrit, on ne range pas */ conteneur.classList.add('bloc-edit'); poserBarreBloc(conteneur, blocDe(x)); });
    x.addEventListener('input', () => ecrireDansDiapo(x));
    x.addEventListener('keydown', ev => { const e = ecran(); /* la diapo du moment, pas celle du branchement : le morph réutilise les nœuds d'une diapo à l'autre */ const all = elementsEditables(); const k = all.indexOf(x); if (p8EnClasse() && (ev.key === 'Enter' || ev.key === 'Escape' || ev.altKey)) { /* (p8-5) en classe, le texte s'écrit, la structure ne change pas : Entrée passe au texte suivant */ if (ev.key === 'Enter') { ev.preventDefault(); ev.stopPropagation(); const n = all[k + 1]; if (n) focaliser(n); else x.blur(); } else if (ev.altKey) { ev.preventDefault(); ev.stopPropagation(); } return; } if (['Tab', 'Enter', 'Escape'].includes(ev.key) || (ev.altKey && /^Arrow/.test(ev.key))) ev.stopPropagation(); /* le clavier global (Échap ferme, flèches naviguent) ne reçoit pas ce que l'atelier traite */ if (ev.key === 'Tab') { ev.preventDefault(); const n = all[k + (ev.shiftKey ? -1 : 1)]; if (n) focaliser(n); return; } if (ev.key === 'Enter') { ev.preventDefault(); const b = blocDe(x); if (!b || b.ei === 't') { const n = all[k + 1]; if (n) focaliser(n); return; } if (p8DiapoASchema(e)) { toast('Pas d\'élément en plus : ' + P8_UNE + '.'); return; } /* (p8-3) */ const bloc = e.blocs[b.bi]; bloc.el = bloc.el || []; bloc.el.splice(b.ei + 1, 0, ''); p8NotesElement(S.di, b.bi, b.ei + 1, 'inserer'); /* (p8-5c) */ marquerModif({ di: S.di, bi: b.bi, ajout: b.ei + 1 }); dr_tout(); setTimeout(() => { const nv = mur.querySelector(`[data-p="${b.bi}.${b.ei + 1}"]`); if (nv) { nv.setAttribute('data-vide', '1'); focaliser(nv); } }, 0); return; } if (ev.key === 'Escape') { const b = blocDe(x); if (b && b.ei !== 't' && !x.textContent.trim()) { ev.preventDefault(); const bloc = e.blocs[b.bi]; if ((bloc.el || []).length > 1) { bloc.el.splice(b.ei, 1); p8NotesElement(S.di, b.bi, b.ei, 'supprimer'); /* (p8-5c) */ marquerModif({ di: S.di, bi: b.bi, retrait: b.ei }); dr_tout(); setTimeout(() => { const prev = mur.querySelector(`[data-p="${b.bi}.${Math.max(0, b.ei - 1)}"]`); if (prev) focaliser(prev); }, 0); } } return; } if (ev.altKey && (ev.key === 'ArrowUp' || ev.key === 'ArrowDown')) { ev.preventDefault(); const b = blocDe(x); if (b) deplacerBloc(b.bi, ev.key === 'ArrowUp' ? -1 : 1); } });
  }); }

function poserBarreBloc(conteneur, b){ const mur = $('mur'); mur.querySelectorAll('.bloc-barre').forEach(z => z.remove()); if (!b) return; const e = ecran(); const bloc = e.blocs[b.bi]; if (!bloc) return; const n = (bloc.el || []).length; const barre = document.createElement('div'); barre.className = 'bloc-barre'; barre.innerHTML = `<span class="nom">BLOC ${b.bi + 1} · ${dr_esc((bloc.t || '').toUpperCase())} · ${n} ÉLÉMENT${n > 1 ? 'S' : ''}</span><button data-bb="haut" title="Monte ce bloc d\'un cran dans la diapo (Alt + ↑)" ${b.bi === 0 ? 'disabled' : ''}>▲</button><button data-bb="bas" title="Descend ce bloc d\'un cran (Alt + ↓)" ${b.bi >= e.blocs.length - 1 ? 'disabled' : ''}>▼</button><span class="sep"></span><button data-bb="etape" ${p8DiapoASchema(e) ? 'disabled title="Cette diapo a son schéma : une étape de plus va dans la diapo suivante — écris-la là, ou insère une diapo (Ctrl + Entrée)."' : 'title="Ajoute un élément à la fin de ce bloc (Entrée en fin de ligne fait pareil)"'}>+ étape</button><button data-bb="suppr" title="Supprime ce bloc — le site demande confirmation si des réponses d\'élèves y sont accrochées (1.8)">✕</button>`; conteneur.appendChild(barre); barre.querySelectorAll('[data-bb]').forEach(bt => bt.addEventListener('mousedown', ev => ev.preventDefault())); barre.querySelector('[data-bb="haut"]').onclick = () => deplacerBloc(b.bi, -1); barre.querySelector('[data-bb="bas"]').onclick = () => deplacerBloc(b.bi, 1); barre.querySelector('[data-bb="etape"]').onclick = () => { bloc.el = bloc.el || []; bloc.el.push(''); marquerModif({ di: S.di, bi: b.bi, ajout: bloc.el.length - 1 }); dr_tout(); setTimeout(() => { const nv = mur.querySelector(`[data-p="${b.bi}.${bloc.el.length - 1}"]`); if (nv) { nv.setAttribute('data-vide', '1'); focaliser(nv); } }, 0); }; barre.querySelector('[data-bb="suppr"]').onclick = () => supprimerBloc(b.bi); }

function deplacerBloc(bi, sens){ const e = ecran(); const j = bi + sens; if (j < 0 || j >= e.blocs.length) return; const t = e.blocs[bi]; e.blocs[bi] = e.blocs[j]; e.blocs[j] = t; p8NotesBloc(S.di, bi, 'echanger', j); /* (p8-5c) */ marquerModif({ di: S.di, bloc: bi, vers: j }); dr_tout(); setTimeout(() => { const el = $('mur').querySelector(`[data-p^="${j}."]`); if (el) focaliser(el, false); }, 0); }

function supprimerBloc(bi){ const e = ecran(); const st = parDiapo[K(S.di)] || { reps: {} }; const reps = Object.keys(st.reps || {}).filter(k => +k === bi && (st.reps[k] || []).length).length; if (reps && !confirm('Des réponses d\'élèves sont accrochées à ce bloc : les supprimer avec lui ?')) return; if (e.blocs.length <= 1) { alert('Une diapo garde au moins un bloc.'); return; } e.blocs.splice(bi, 1); p8NotesBloc(S.di, bi, 'supprimer'); /* (p8-5c) */ marquerModif({ di: S.di, supprime: bi, reps }); dr_tout(); }

setInterval(() => { const sv = $('at-save'); if (!sv || !S.atelier) return; if (S.atelierDirty) { const d = Math.ceil((3000 - (Date.now() - S.atelierDirty)) / 1000); if (d <= 0) { S.atelierDirty = null; S.atelierSaved = Date.now(); sv.className = 'at-save'; sv.textContent = '✔ enregistré'; journal('atelier-enregistre', { di: S.di }); } else sv.textContent = '● modification en cours — enregistrement dans ' + d + ' s'; } else if (S.atelierSaved) { const n = Math.round((Date.now() - S.atelierSaved) / 1000); sv.textContent = '✔ enregistré' + (n >= 1 ? ' il y a ' + (n < 60 ? n + ' s' : Math.round(n / 60) + ' min') : ''); } }, 1000);

function dr_tout(){ setTimeout(atSomSuivreCourant, 0); /* E1 : la colonne du site suit la diapo (lisait DR.dr_ecranCourant par le pont) */ setTimeout(brancherDocs, 0); if (S.repetition || p8EnClasse()) setTimeout(brancherAtelier, 0); /* (p8-4) en répétition aussi, tout texte s'écrit d'un clic ; (p8-5) et en classe, dans la copie */ if (S.atelier) { observerMur(); setTimeout(brancherAtelier, 0); p8GardesBarre(); /* (p8-3) les gestes grisés d'une diapo à schéma */ const ab = $('at-bloc'); if (ab && !ab._ok) { ab._ok = true; ab.onclick = () => choixObjet(); } const ai = $('at-image'); if (ai && !ai._ok) { ai._ok = true; ai.onclick = () => choixObjet('image'); } const af = $('at-fiche'); if (af && !af._ok) { af._ok = true; af.onclick = () => choixObjet('fiche'); } const av = $('at-video'); if (av && !av._ok) { av._ok = true; av.onclick = () => { S.editerVideo = null; choixObjet('video'); }; } const ad = $('at-doc'); if (ad && !ad._ok) { ad._ok = true; ad.onclick = () => choixObjet('doc'); } const ae = $('at-etape'); if (ae && !ae._ok) { ae._ok = true; ae.onclick = () => { const e = ecran(); if (!e || e.role === 'fin') return; const b = document.activeElement && blocDe(document.activeElement); const bi = b ? b.bi : e.blocs.length - 1; const bloc = e.blocs[bi]; if (!bloc) return; bloc.el = bloc.el || []; bloc.el.push(''); marquerModif({ di: S.di, bi, ajout: bloc.el.length - 1 }); dr_tout(); setTimeout(() => { const nv = $('mur').querySelector('[data-p="' + bi + '.' + (bloc.el.length - 1) + '"]'); if (nv) { nv.setAttribute('data-vide', '1'); focaliser(nv); } }, 0); }; }  const v = $('volet'); if (v) { const hv = voletAtelier(); if (v.dataset.atelier !== hv) { v.innerHTML = hv; v.dataset.atelier = hv; v.querySelectorAll('[data-at-di]').forEach(d => d.onclick = () => { S.di = +d.dataset.atDi; S.page = null; journal('atelier-diapo', { di: S.di }); dr_tout(); }); } } rendreDroiteAtelier(); const aj = $('at-jouer'); if (aj && !aj._ok) { aj._ok = true; aj.onclick = () => { journal('atelier-jouer-en-avance', { di: S.di }); lancerRepetition(); }; } } try { ligneSuite(); } catch (e) {} if (S.enFin && !S.preparation && ecran().role === 'fin' && S._finRenduPour !== 'fin') { S._finRenduPour = 'fin'; setTimeout(() => ouvrirFin(true), 0); } else if (S.enFin && ecran().role !== 'fin') S._finRenduPour = null; if (S.preparation) { try { dimensionner(); } catch (e) {} } $('droite').classList.toggle('cahier', ecran().role === 'fin'); if (S.t5 && !S.close) { if (ecran().role === 'fin') alerteFermer(); else if (!S.alerteOuverte && $('al-ligne').style.display === 'none' && S.palier) alerteOuvrir(); }
  dimensionner(); if (!S.mur || S.mur.di !== S.di || S.mur.si !== S.si) S.arrivee = { di: S.di }; const e = ecran(); const et = etatComplet(); et.pilote = true; et.ecrire = p8EcritureOuverte(); /* (p8-4) */ if (!S.atelier && !S.repetition) et.textes = p8TextesCopie(e, et.textes); /* (p8-5) la copie de la classe, au pilote et au tableau */ rendre(mur, et); mur.className = 'mur pilote' + (S.mode === 'lum' ? ' mode-lum' : S.mode === 'ecr' ? ' mode-ecr' : '') + (et.bandeau ? ' avec-bandeau' : ''); et.pilote = false;
  S.page = et.page; S.pagesCourantes = et.pages; etatDiapo().fsBloc = Object.assign({}, et.fsBloc || {});
  if (!S.gel) pousser(et); else S.attente = et;
  $('numero').innerHTML = S.atelier ? (function(){ const e = ecran(); const a = actDe(e); const cr = creneauDe(S.di); return `<b>Atelier · Diapo ${rangDe(S.di, e.heure)} sur ${ordreHeure(e.heure).length} · heure ${e.heure}${a ? ' · activité ' + a.num : ''} · ${dr_esc(e.role === 'fin' ? 'Cahier de textes' : e.act)}</b> <span style="color:var(--texte2)">· prévue ${e.role === 'fin' ? 5 : (e.dur || 0)} min · H${e.heure} ${hhmm(cr.debut).replace(':', ' h ')} → ${hhmm(cr.fin).replace(':', ' h ')}</span>`; })() : `${rangDe(S.di) ? 'Diapo ' + rangDe(S.di) + ' sur ' + ordreHeure(S.heure).length + ' · heure ' + S.heure : 'Hors de l\'heure ' + S.heure}${numDe(e) ? ' · activité ' + numDe(e) + (actDe(e).diapos.length > 1 ? ' (' + (actDe(e).diapos.indexOf(S.di) + 1) + '/' + actDe(e).diapos.length + ')' : '') : (e.role === 'fin' ? ' · Cahier de textes' : (e.role ? ' · ' + (e.role === 'reactivation' ? 'réactivation' : e.role) : ''))}`; $('dtitre').textContent = `· ${e.act} · prévue ${e.dur} min · H${e.heure}${e.role ? ' · ' + (e.role === 'bilan' ? 'bilan de la séance' : e.role === 'fin' ? 'les cinq minutes réservées' : 'réactivation') : ''}`;
  $('compte').textContent = (S.preparation && e.role === 'fin') ? 'préparation — rien n\'est montré à la classe' : elements(e).length ? `${etatDiapo().nDev} / ${elements(e).length} dévoilés` : (e.blocs[0] && e.blocs[0].t === 'video' ? 'vidéo — ▶ jusqu\'au repère suivant' : 'rien à dévoiler');
  p8RendreNotes(); /* (p8-5c) les notes par paragraphe, accrochées aux éléments */
  vueDroite(et);
  const pastille = $('pastille'); const nC = (S.comm[e.eid] || []).length; pastille.style.display = nC ? 'block' : 'none'; pastille.textContent = '💬 ' + nC;
  ouOnEnEst(); volet(); brancherAjout(); brancherMenus(); participation(); temoin(); alerteVideo(); $('taille-l').textContent = TAILLES[S.taille].l;
  const bc = $('bcoche'); bc.style.display = (e.role === 'bilan') ? 'inline-block' : 'none'; bc.textContent = (S.bilanCoche ? '☑' : '☐') + ' Les élèves ont écrit le bilan'; bc.classList.toggle('or', !!S.bilanCoche);
  if (S.gel) $('temoin-txt').textContent = `La classe est sur la ${libDiapo(S.gel.di)} — ${dr_seances()/* E1 : lisait DATA.seances */[S.gel.si].ecrans[S.gel.di].act}.`;
}

function reprisesPrevuesHtml(){ const rp = (S.reprisesPrevues || {})[S.heure] || []; const faites = (S.oraux || {})[S.heure] || []; return rp.filter(q => !faites.some(o => (o.notions || []).includes(q.notion))).map(q => `<div class="rep-prevue" data-reprise="${dr_esc(q.notion)}" title="Reprise à l'oral prévue à l'ouverture de l'heure : un clic ouvre « Expliqué à l'oral » avec la notion déjà cochée">↺ reprise à l'oral de <b>${dr_esc(q.lib)}</b> avant « ${dr_esc(q.act)} »</div>`).join(''); }

function ouOnEnEst(){ const e = ecran(); const acts = activitesDeLHeure(); const prevu = acts.reduce((t, a) => t + dureeDe(a), 0) + 5; const misAPart = (S.coupures || []).filter(c => !c.compte).reduce((t, c) => t + c.duree, 0); const utile = 46 - Math.floor(S.ecoule / 60) + misAPart + Math.floor(S.ecoule / 60); const debord = prevu - 50; /* 50 = 55 − 5 réservées au cahier */
  $('ou').innerHTML = `<span>${dr_esc(e.act)} — en cours</span><b>H${S.heure} · ${prevu} min prévues / 50 utiles</b>`; $('retard').textContent = debord > 0 ? `l'heure dépasse de ${debord} min` : '';
  /* (c) la liste des durées par activité (5.4 bis) : [min] hh:mm titre · l'état de worktrack */
  let t = dr_heureDe(S.heure)/* E1 : lisait HEURES_SIM */.base; const enCours = actDe(e); const focus = document.activeElement && document.activeElement.classList.contains('dur-in') ? document.activeElement.dataset.a : null;
  const lignes = acts.map(a => { const w = etatWorktrack(a) || { k: 'attend', txt: '' }; const debut = t; t += dureeDe(a) * 60000; const cours = enCours && enCours.id === a.id; const val = focus === a.id ? document.activeElement.value : dureeDe(a); return `<div class="dur-l${w.k === 'fin' ? ' faite' : ''}${cours ? ' cours' : ''}"><input class="dur-in" data-a="${a.id}" value="${val}" title="Les minutes prévues pour cette activité — change-les pendant le cours : les heures de début de la suite se recalent ; ça vaut pour cette classe, la trame ne change que si tu verses à la clôture"><span class="dur-h">${hhmm(debut)}</span><span class="dur-t" title="${dr_esc(a.titre || '')}">A${a.num} · ${dr_esc(a.titre || '')}</span><span class="dur-e ${w.k}">${w.txt}</span></div>`; });
  lignes.push(`<div class="dur-l cahier"><input class="dur-in" value="5" disabled title="Les cinq minutes réservées au cahier de textes ne se changent pas"><span class="dur-h">${hhmm(heureCahier())}</span><span class="dur-t">Cahier de textes</span><span class="dur-e"></span></div>`);
  const d = $('durees'); poserHtml(d, lignes.join('') + reprisesPrevuesHtml()); d.querySelectorAll('[data-reprise]').forEach(l => l.onclick = () => { const q = ((S.reprisesPrevues || {})[S.heure] || []).find(x => x.notion === l.dataset.reprise); ouvrirOral({ act: null, notion: l.dataset.reprise, texte: '' }); if (q) journal('reprise-prevue-ouverte', { notion: q.notion }); }); d.querySelectorAll('.dur-in:not([disabled])').forEach(inp => { const valider = () => { const a = activitesDeLHeure().find(x => x.id === inp.dataset.a); if (!a) return; const v = Math.max(1, Math.min(120, parseInt(inp.value, 10) || dureeDe(a))); if (v === dureeDe(a)) { inp.value = v; return; } const avant = dureeDe(a); S.durees = S.durees || {}; S.durees[a.id] = v; journal('duree-changee', { act: a.id, num: a.num, avant, apres: v }); dr_tout(); }; inp.onkeydown = ev => { if (ev.key === 'Enter') { ev.preventDefault(); valider(); inp.select(); } if (ev.key === 'Escape') { inp.value = dureeDe(activitesDeLHeure().find(x => x.id === inp.dataset.a)); inp.blur(); } ev.stopPropagation(); }; inp.onblur = valider; }); }

function volet(){ if (S.atelier) return; const v0 = $('volet'); if (v0 && v0.dataset.atelier) delete v0.dataset.atelier; /* (p6) le volet du pilotage a repris la place : la colonne de l'atelier se réécrira */ /* (p1) en atelier, la colonne du chapitre remplace les vignettes */ const v = $('volet'); const o = ordreHeure(S.heure); const autres = seance().ecrans.map((e, i) => i).filter(i => !o.includes(i)); let h = `<h5><span>Heure ${S.heure} · ${o.length} diapos</span></h5>`;
  const vig = (i, rang, hors) => { const e = seance().ecrans[i]; const k = K(i); const nC = (S.comm[e.eid] || []).length; const dec = decisionDe(e); const gl = glisseeDe(e);
    return `<div class="vig ${i === S.di ? 'cour' : ''} ${dec && !gl ? 'retiree' : ''} ${vuMax[k] ? 'jouee' : ''} ${hors ? 'hors' : ''}" data-i="${i}" title="${numDe(e) ? 'Activité ' + dr_esc(String(numDe(e))) + ' — ' : ''}${dr_esc(e.act)}${gl ? ' — glissée de l\'heure ' + e.heure + (gl.choix === 'terminer' ? ', à terminer' : gl.choix === 'preparer' ? ', préparée à la maison' : '') : dec ? ' — ' + dr_esc(libDecision(dec)) : ''}${hors ? ' — pas dans cette heure' : ''}"><span class="dr-n">${rang}</span><div class="mini" data-i="${i}"></div><span class="dr-h">${gl ? '↩ H' + e.heure : 'H' + e.heure}</span>${e.role ? `<span class="role">${e.role === 'bilan' ? 'bilan' : (e.role === 'fin' ? 'cahier de textes' : 'réactivation')}</span>` : ''}${nC ? `<span class="past">💬${nC}</span>` : ''}</div>`; };
  o.forEach((i, r) => { h += vig(i, r + 1, false); });
  if (autres.length) { h += `<h5 style="margin-top:10px"><span>Pas dans cette heure</span></h5>`; autres.forEach(i => { h += vig(i, '·', true); }); }
  poserHtml(v, h); miniatures(v); const c = v.querySelector('.vig.cour'); if (c) { const r = c.offsetTop; if (r < v.scrollTop || r + c.offsetHeight > v.scrollTop + v.clientHeight) v.scrollTop = r - v.clientHeight / 2; } }

function miniatures(v){ /* chaque vignette est la diapo elle-même, rendue et réduite ; on ne la re-rend que si son contenu a changé */
  v.querySelectorAll('.mini[data-i]').forEach(m => { const i = +m.dataset.i; const e = seance().ecrans[i]; const st = parDiapo[K(i)] || {}; const w = m.clientWidth || 150; const sc = w / 1096; m.style.height = Math.round(616 * sc) + 'px';
    const hash = JSON.stringify([e.act, st.textes, st.reps, st.tailles, S.videoPos[e.eid], w, e.role === 'fin' ? [(S.cahierScroll || {})[S.heure], (S.cahierGrand || {})[S.heure] !== false, S.finVue] : 0]); if (m.dataset.hash === hash) return; m.dataset.hash = hash;
    let inner = m.querySelector(':scope > .mur'); if (!inner) { inner = document.createElement('div'); inner.className = 'mur'; m.appendChild(inner); } inner.style.transform = `scale(${sc})`;
    const et = { si: S.si, di: i, nDev: elements(e).length, lum: [], ecr: [], taille: 1, page: 0, reps: st.reps || {}, tailles: st.tailles || {}, textes: st.textes || {}, fsBloc: {}, pilote: false, videoPos: S.videoPos[e.eid] || 0, sansPages: true }; rendre(inner, et); const pg = inner.querySelector('.page'); if (pg) pg.textContent = ''; }); }

function temoin(){ $('temoin-mini').textContent = S.gel ? '❄ tableau gelé' : ''; }
